    #[cfg(feature = "postgres")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn get_edge_detection_events_returns_v020_rows_postgres() {
        let Some(dsn) = crate::test_pg::dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let signer = test_signer();
        let engine = Engine::with_signer(signer, &dsn)
            .await
            .expect("construct PG engine");
        let pg = engine.postgres_backend().expect("pg backend");

        // Bootstrap a federation_keys row to satisfy the FK.
        // v62 (E3): the FK target is an edition-2 key:record; a per-run seed
        // keeps the shared PG DB collision-free.
        use crate::federation::edition2::fixture_switch as e2;
        let suspect_id = e2::put_key(
            pg.as_ref(),
            &format!("k-suspect-{}", uuid::Uuid::new_v4().simple()),
            &[crate::federation::types::identity_type::AGENT],
        )
        .await;

        // INSERT three edge_detection_events via the pool client.
        let tenant_a = format!("tnt-A-{}", uuid::Uuid::new_v4().simple());
        let tenant_b = format!("tnt-B-{}", uuid::Uuid::new_v4().simple());
        let base_ts = chrono::Utc::now();
        let client = pg.checkout().await.unwrap();
        let id_a1 = uuid::Uuid::new_v4();
        let id_a2 = uuid::Uuid::new_v4();
        let id_b = uuid::Uuid::new_v4();
        client
            .execute(
                "INSERT INTO cirislens.edge_detection_events (\
                    detection_id, tenant_id, detector_kind, subject_key_id, \
                    observed_at, evidence, severity, signature, signing_key_id, \
                    signature_verified, persist_row_hash\
                 ) VALUES \
                 ($1, $2, 'unconsented_external_probe', $3, $4, $5::jsonb, 'warn', \
                  'sig', 'lens-detector', TRUE, 'hash'), \
                 ($6, $7, 'excessive_recursion', $8, $9, $10::jsonb, 'warn', \
                  'sig', 'lens-detector', TRUE, 'hash'), \
                 ($11, $12, 'consent_gate_leak', $13, $14, $15::jsonb, 'info', \
                  'sig', 'lens-detector', FALSE, 'hash')",
                &[
                    &id_a1,
                    &tenant_a,
                    &suspect_id,
                    &(base_ts - chrono::Duration::minutes(2)),
                    &serde_json::json!({"probed": "x"}),
                    &id_a2,
                    &tenant_a,
                    &suspect_id,
                    &(base_ts - chrono::Duration::minutes(1)),
                    &serde_json::json!({"probed": "y"}),
                    &id_b,
                    &tenant_b,
                    &suspect_id,
                    &base_ts,
                    &serde_json::json!({"probed": "z"}),
                ],
            )
            .await
            .unwrap();

        // tenant filter → exactly tenant_a's 2 rows
        let alpha = engine
            .get_edge_detection_events(crate::derived::EdgeEventFilter {
                tenant_id: Some(tenant_a.clone()),
                ..Default::default()
            })
            .await
            .unwrap();
        assert_eq!(alpha.len(), 2);
        for r in &alpha {
            assert_eq!(r.tenant_id, tenant_a);
            assert!(r.signature_verified);
        }

        // recorded_after cursor
        let cursor = base_ts - chrono::Duration::minutes(1);
        let after = engine
            .get_edge_detection_events(crate::derived::EdgeEventFilter {
                peer_key_id: Some(suspect_id.clone()),
                recorded_after: Some(cursor),
                ..Default::default()
            })
            .await
            .unwrap();
        // The base_ts row is strictly > cursor; the two earlier ones are not.
        assert!(after.iter().any(|r| r.tenant_id == tenant_b));
        assert!(after.iter().all(|r| r.observed_at > cursor));
    }

    #[cfg(feature = "postgres")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn subscribe_detection_events_yields_new_events_only_postgres() {
        use crate::derived::EventFilter;

        let Some(dsn) = crate::test_pg::dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let signer = test_signer();
        let engine = Engine::with_signer(signer, &dsn)
            .await
            .expect("construct PG engine");
        let pg = engine.postgres_backend().expect("pg backend");
        // v62.0.0 (P8-fix11) — a detection is its conferred detector's own
        // edition-2 statement: this node accepts a root that confers
        // `infra:detect` on the test detector.
        crate::derived::detection_row::test_support::confer(&**pg).await;

        // v31.0.0 (CIRISPersist#658) — ONE trace_id for both rows. The
        // per-run uuid keeps this test isolated from concurrent PG runs, but
        // the pre- and post-subscribe rows used to carry DIFFERENT trace_ids,
        // which meant the subscription's own filter already excluded the
        // pre-subscribe row — so `assert_ne!` below could not fail whatever
        // the cursor did, and the sqlite arm's actual claim had no postgres
        // parity at all. Same trace, so the CURSOR is the only thing that can
        // exclude the older row.
        let trace = format!("tr-SUB-{}", uuid::Uuid::new_v4().simple());

        // Seed a row BEFORE subscribing.
        let before_ts = chrono::Utc::now() - chrono::Duration::seconds(10);
        let pre_ev = de_event_fixture(&trace, b"canon-PRE", before_ts);
        crate::derived::detection_row::test_support::state(&**pg, &pre_ev).await;

        // Subscribe with a trace_id filter to isolate from concurrent runs.
        let mut stream = Box::pin(engine.subscribe_detection_events(EventFilter {
            trace_id: Some(trace.clone()),
            ..Default::default()
        }));

        // Insert NEW row after subscribe. No delay is needed: the cursor
        // latches on `Utc::now()` synchronously inside
        // `subscribe_detection_events`, and `EventFilter.since` is inclusive.
        let new_ts = chrono::Utc::now();
        let new_ev = de_event_fixture(&trace, b"canon-NEW", new_ts);
        crate::derived::detection_row::test_support::state(&**pg, &new_ev).await;

        let yielded = next_detection_event(&mut stream)
            .await
            .unwrap_or_else(|| panic!("{}", subscribe_never_delivered("the after-subscribe row")));
        assert_ne!(
            yielded.detection_id, pre_ev.detection_id,
            "the FIRST row a subscription yields was written BEFORE it subscribed — the \
             subscribe-time cursor did not latch and the subscriber is replaying history"
        );
        assert_eq!(yielded.detection_id, new_ev.detection_id);
        drop(stream);
    }

