    /// A local-tier `trace:complete:v1` `LocalAttestationInput`, shaped
    /// like `ingest::build_trace_attestation_input` (attestation_type
    /// `scores`, self-subject, `cohort_scope = self`, an inline (empty
    /// object) `trace` — the trace-dimension admission gate only checks
    /// shape, not content).
    #[cfg(feature = "sqlite")]
    fn build_509_trace_input(
        derived: &str,
        trace_id: &str,
    ) -> crate::federation::types::LocalAttestationInput {
        crate::federation::types::LocalAttestationInput {
            attestation_id: None,
            attesting_key_id: derived.to_owned(),
            attested_key_id: None,
            attestation_type: crate::federation::types::attestation_type::SCORES.to_owned(),
            weight: None,
            expires_at: None,
            attestation_envelope: crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({
                    "dimension": "trace:complete:v1",
                    "trace_id": trace_id,

                    "agent_id_hash": "agent-hash-509",
                    "trace": {},
                }),
            )
            .unwrap(),
            subject_key_ids: vec![derived.to_owned()],
            cohort_scope: crate::federation::types::cohort_scope::SELF.to_owned(),
            scrub_signature_classical: None,
            scrub_signature_pqc: None,
        }
    }

    /// Emit a self-authored `consent:replication:v1` grant naming `peer`
    /// as the consented recipient and `prefixes` as the covered
    /// `attestation_prefixes`, via `emit_attestation_self` (so it lands
    /// federation-tier, hybrid-signed, and drives the E7
    /// `consent_peer_set` projection exactly like a real node would).
    #[cfg(feature = "sqlite")]
    async fn emit_509_grant(engine: &Engine, peer: &str, prefixes: &[&str]) -> String {
        let envelope = crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
            "dimension": crate::federation::consent_peer_set::DIMENSION,
            "subject_key_ids": [peer],
            "payload": {"grants": "replication", "attestation_prefixes": prefixes},
            "subject_kind": "consent_replication",
        }))
        .unwrap();
        let mut input = crate::federation::EmitAttestationInput::with_envelope(
            crate::federation::types::attestation_type::SCORES,
            envelope,
            crate::federation::types::cohort_scope::FEDERATION,
        );
        input.subject_key_ids = vec![peer.to_owned()];
        engine
            .emit_attestation_self(input)
            .await
            .expect("509 grant emits")
    }

    /// Like [`emit_509_grant`] but declares an explicit `audience` in the
    /// payload (CIRISPersist#530 tests exercise the repair sweep's
    /// broaden-only guard, which turns on the covering grant's resolved
    /// audience).
    ///
    /// Gated on `sqlite` alone — the feature of its ONE caller. Under
    /// `any(sqlite, postgres)` this was dead code on a postgres-without-sqlite
    /// build (`--features pyo3`, the published-wheel shape), which
    /// `--all-targets -D warnings` refuses.
    #[cfg(feature = "sqlite")]
    async fn emit_509_grant_audience(
        engine: &Engine,
        peer: &str,
        prefixes: &[&str],
        audience: &str,
    ) -> String {
        emit_509_grant_audience_in(engine, peer, prefixes, audience, None).await
    }

    /// `emit_509_grant_audience`, naming the cohort a targeted audience
    /// places rows in (its cohort-target alias, `community_key_id`). Gated as
    /// its sibling is: `emit_attestation_self` needs a backend.
    #[cfg(feature = "sqlite")]
    async fn emit_509_grant_audience_in(
        engine: &Engine,
        peer: &str,
        prefixes: &[&str],
        audience: &str,
        room: Option<&str>,
    ) -> String {
        let mut value = serde_json::json!({
            "dimension": crate::federation::consent_peer_set::DIMENSION,
            "subject_key_ids": [peer],
            "payload": {
                "grants": "replication",
                "attestation_prefixes": prefixes,
                "audience": audience,
            },
            "subject_kind": "consent_replication",
        });
        if let Some(room) = room {
            value["community_key_id"] = serde_json::json!(room);
        }
        let envelope = crate::federation::envelope::EnvelopeCore::from_value(value).unwrap();
        let mut input = crate::federation::EmitAttestationInput::with_envelope(
            crate::federation::types::attestation_type::SCORES,
            envelope,
            crate::federation::types::cohort_scope::FEDERATION,
        );
        input.subject_key_ids = vec![peer.to_owned()];
        engine
            .emit_attestation_self(input)
            .await
            .expect("509 grant (with audience) emits")
    }

    /// Emit a self-authored `withdraws` referencing `target_id` — the E7
    /// revocation fold's trigger shape (`references_attestation_id` +
    /// rule-1 producer self-revocation, since the same engine authored
    /// both the target and the withdraws).
    #[cfg(feature = "sqlite")]
    async fn emit_509_withdraws(engine: &Engine, target_id: &str) -> String {
        let envelope = crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
            // v62 (E3, round 6): a composer's payload is the common members
            // and `refs.target` (P1d); the earlier `withdrawal_reason` is none.
            "references_attestation_id": target_id,
        }))
        .unwrap();
        let input = crate::federation::EmitAttestationInput::with_envelope(
            crate::federation::types::attestation_type::WITHDRAWS,
            envelope,
            crate::federation::types::cohort_scope::FEDERATION,
        );
        engine
            .emit_attestation_self(input)
            .await
            .expect("509 withdraws emits")
    }

    /// The (c) chokepoint: emitting a self-authored grant whose
    /// `attestation_prefixes` covers an existing local-tier trace row
    /// promotes it to federation tier — WITHOUT an explicit
    /// `promote_consented_backlog` call. v62 (E3b, P8): the row crosses in
    /// place on its own statement (scope `self`, the same bytes) and the
    /// grant's audience is reached by ONE restatement. A subsequent explicit
    /// sweep is idempotent (nothing left to promote).
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn consent_sweep_promotes_covered_backlog_509() {
        use crate::federation::attestation_query::test_support::AllAttestations as _;
        use crate::federation::edition2::emit::carried_statement;
        use crate::federation::edition2::fixture_switch as e2;
        use crate::federation::types::{attestation_tier, cohort_scope};
        use crate::federation::FederationDirectory;

        let (engine, sq, node) = engine_with_registered_agent("node-509a").await;
        let signer = engine
            .composite_signer("e3b sweep witness")
            .expect("a composite signer");
        let trace_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509a-1")).await;
        let before = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(before.tier, attestation_tier::LOCAL);

        // (c) hook: emitting the self-authored grant fires the sweep with
        // no explicit call.
        let _grant_id = emit_509_grant(&engine, &e2::kid("peer-509a"), &["trace:"]).await;

        let after = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(
            after.tier,
            attestation_tier::FEDERATION,
            "the (c) hook promotes the covered local backlog during the grant's own emit"
        );
        assert_eq!(
            after.cohort_scope,
            cohort_scope::SELF,
            "the crossing never changes the scope — it is one of the bytes"
        );
        assert_eq!(
            carried_statement(&after),
            carried_statement(&before),
            "in place, on the row's own statement"
        );
        let widened: Vec<_> = sq
            .all_attestations_by(&node)
            .await
            .unwrap()
            .into_iter()
            .filter(|a| {
                a.cohort_scope == cohort_scope::FEDERATION
                    && a.attestation_envelope.get("trace_id")
                        == Some(&serde_json::json!("trace-509a-1"))
            })
            .collect();
        assert_eq!(
            widened.len(),
            1,
            "the grant's audience is reached by ONE restatement"
        );

        // Idempotent: an explicit sweep now finds nothing left to promote.
        let report = engine.promote_consented_backlog().await.expect("sweep");
        assert_eq!(report.promoted, 0);
        assert_eq!(report.skipped, 0);
    }

    /// v21.2.0 (#507 × #509) — the `list_attestations_since` VISIBILITY
    /// cursor: a consent-promoted row becomes wire-visible at
    /// `promoted_at`, not `asserted_at`. A pure-delta consumer whose
    /// cursor already passed the row's `asserted_at` must still see it
    /// once promotion happens — under an `asserted_at`-only cursor the
    /// late promotion would be invisible forever.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn promoted_row_appears_in_visibility_delta_507_509() {
        use crate::federation::FederationDirectory;

        // v62 (E3b r3; P8): an edition-2 LOCAL row (it crosses in place on its
        // own statement); the earlier unsigned `attestation_insert_local` row
        // has no in-place crossing.
        let (engine, sq, node) = engine_with_registered_agent("node-509v").await;
        let signer = engine
            .composite_signer("e3b visibility witness")
            .expect("a composite signer");
        let trace_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509v-1")).await;
        // The delta cursor sits exactly AT the row's asserted_at — a
        // strict `>` filter on asserted_at alone would exclude it forever.
        let since = sq
            .get_attestation(&trace_id)
            .await
            .unwrap()
            .expect("row")
            .asserted_at;

        // Ensure promoted_at lands strictly after the cursor even on
        // coarse clocks, then promote via the (c) hook.
        tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        let _grant_id = emit_509_grant(
            &engine,
            &crate::federation::edition2::fixture_switch::kid("peer-509v"),
            &["trace:"],
        )
        .await;
        let after = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(
            after.tier,
            crate::federation::types::attestation_tier::FEDERATION
        );

        let delta = sq
            .list_attestations_since(Some((since, trace_id.clone())), 100)
            .await
            .expect("delta read");
        assert!(
            delta
                .iter()
                .any(|a| a.attestation.attestation_id == trace_id),
            "a row promoted after the consumer's cursor passed its asserted_at \
             must appear in the visibility delta (the promote sweep re-stamps \
             the serve position)"
        );
    }

    /// A grant whose `attestation_prefixes` cover an UNRELATED dimension
    /// (`capacity:`) must not promote a `trace:complete:v1` backlog row —
    /// neither via the (c) hook during the grant's own emit, nor via an
    /// explicit sweep afterward. v62 (E3b): an edition-2 local row.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn consent_sweep_ignores_uncovered_dimension_509() {
        use crate::federation::edition2::fixture_switch as e2;
        use crate::federation::FederationDirectory;

        let (engine, sq, node) = engine_with_registered_agent("node-509b").await;
        let signer = engine
            .composite_signer("e3b sweep witness")
            .expect("a composite signer");
        let trace_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509b-1")).await;

        let _grant_id = emit_509_grant(&engine, &e2::kid("peer-509b"), &["capacity:"]).await;

        let after = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(
            after.tier,
            crate::federation::types::attestation_tier::LOCAL,
            "a grant covering an unrelated prefix must not promote the trace backlog"
        );

        let report = engine.promote_consented_backlog().await.expect("sweep");
        assert_eq!(report.promoted, 0);
        assert_eq!(report.skipped, 0);
    }

    /// Withdrawing a grant folds the E7 `consent_peer_set` projection
    /// (the grant is no longer LIVE), so a NEW local-tier row inserted
    /// after the withdraws does not get promoted by a subsequent sweep —
    /// revoked consent no longer promotes. v62 (E3b): edition-2 local rows.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn consent_sweep_stops_after_withdraw_509() {
        use crate::federation::edition2::fixture_switch as e2;
        use crate::federation::FederationDirectory;

        let (engine, sq, node) = engine_with_registered_agent("node-509c").await;
        let signer = engine
            .composite_signer("e3b sweep witness")
            .expect("a composite signer");
        let trace1_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509c-1")).await;

        let grant_id = emit_509_grant(&engine, &e2::kid("peer-509c"), &["trace:"]).await;
        let after1 = sq.get_attestation(&trace1_id).await.unwrap().expect("row");
        assert_eq!(
            after1.tier,
            crate::federation::types::attestation_tier::FEDERATION,
            "trace1 promotes during the grant's own emit (the (c) hook)"
        );

        // Withdraw the grant — E7's projection folds it: consent_peer_set
        // loses the row sourced from `grant_id`, so it is no longer LIVE.
        let _withdraws_id = emit_509_withdraws(&engine, &grant_id).await;
        assert!(
            sq.list_consent_peers(&node).await.unwrap().is_empty(),
            "the withdraws must fold the consent_peer_set projection"
        );

        let trace2_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509c-2")).await;

        let report = engine.promote_consented_backlog().await.expect("sweep");
        assert_eq!(report.promoted, 0, "revoked consent no longer promotes");
        assert_eq!(report.skipped, 0);

        let after2 = sq.get_attestation(&trace2_id).await.unwrap().expect("row");
        assert_eq!(
            after2.tier,
            crate::federation::types::attestation_tier::LOCAL,
            "trace2 stays local — the grant that would have covered it is no longer live"
        );
    }

    /// No live grants at all ⇒ the sweep is a strict no-op: zero report,
    /// local rows untouched. v62 (E3b): an edition-2 local row.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn consent_sweep_no_grants_noop_509() {
        use crate::federation::FederationDirectory;

        let (engine, sq, node) = engine_with_registered_agent("node-509d").await;
        let signer = engine
            .composite_signer("e3b sweep witness")
            .expect("a composite signer");
        let trace_id = local_e2_row(&*sq, signer, e2_trace_input(&node, "trace-509d-1")).await;

        let report = engine.promote_consented_backlog().await.expect("sweep");
        assert_eq!(report.promoted, 0);
        assert_eq!(report.skipped, 0);

        let after = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(
            after.tier,
            crate::federation::types::attestation_tier::LOCAL,
            "no grants ⇒ local rows untouched"
        );
    }

    // ── v21.3.0 (CIRISPersist#510 P1) — the closed grammar drives the
    //    sweep: policy-parsed grants, audience resolution, restriction
    //    (strip_field) application, expiry.

    /// Emit a self-authored `consent:replication:v1` grant carrying an
    /// arbitrary #510 payload (audience / restrictions / valid_until /
    /// kinds), via `emit_attestation_self` — the #510 analogue of
    /// `emit_509_grant` (which only ever set `attestation_prefixes`).
    #[cfg(feature = "sqlite")]
    async fn emit_510_grant(engine: &Engine, peer: &str, payload: serde_json::Value) -> String {
        let envelope = crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
            "dimension": crate::federation::consent_peer_set::DIMENSION,
            "subject_key_ids": [peer],
            "payload": payload,
            "subject_kind": "consent_replication",
        }))
        .unwrap();
        let mut input = crate::federation::EmitAttestationInput::with_envelope(
            crate::federation::types::attestation_type::SCORES,
            envelope,
            crate::federation::types::cohort_scope::FEDERATION,
        );
        input.subject_key_ids = vec![peer.to_owned()];
        engine
            .emit_attestation_self(input)
            .await
            .expect("510 grant emits")
    }

    // v62 (E3b r3): `promotion_applies_strip_field_510` DELETED. Its subject
    // was an earlier-form unsigned local row (`attestation_insert_local`)
    // crossing in place and a JCS `supersedes` widening that declares
    // `differs_in`; edition 2 crosses only a stated row in place and widens
    // by restatement (P8). The strip rule on edition-2 rows is
    // `consent_sweep_widening_honors_strip_restrictions_510`.

    /// A grant whose payload `valid_until` is already in the PAST does
    /// not cover anything — the sweep promotes zero rows, the same
    /// fail-closed posture `expired_grant_does_not_cover_510` names.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn expired_grant_does_not_cover_510() {
        use crate::federation::FederationDirectory;

        let signer = crate::federation::tier_ingest::test_support::local_signer("node-510exp");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "node-510exp"))
            .await
            .expect("seed key");

        let trace_id = sq
            .attestation_insert_local(build_509_trace_input(&derived, "trace-510exp-1"))
            .await
            .expect("insert local trace");

        let _grant_id = emit_510_grant(
            &engine,
            "peer-510exp",
            serde_json::json!({
                "grants": "transfer",
                "attestation_prefixes": ["trace:"],
                "valid_until": "2020-01-01T00:00:00.000Z",
            }),
        )
        .await;

        // The (c) emit-time hook already ran the sweep once; an explicit
        // second sweep must also promote nothing.
        let report = engine.promote_consented_backlog().await.expect("sweep");
        assert_eq!(report.promoted, 0, "an expired grant covers nothing");
        assert_eq!(report.skipped, 0);

        let after = sq.get_attestation(&trace_id).await.unwrap().expect("row");
        assert_eq!(
            after.tier,
            crate::federation::types::attestation_tier::LOCAL,
            "an expired grant's row stays local — never promoted"
        );
    }

    // ── v9.3.0 (CIRISPersist#247 + #248) CEG-DX foundation ──

    /// #248 — `emit_attestation` produces a federation-tier row whose
    /// attester/scrub key is the signer's DERIVED key_id (so the FK to
    /// `federation_keys` holds when the key is registered under the derived
    /// id — the real-node shape), with a populated hybrid scrub envelope and
    /// a recomputed `original_content_hash`.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_attestation_round_trip_derives_key_id_sqlite() {
        use crate::federation::types::attestation_type::SCORES;
        use crate::federation::FederationDirectory;

        // Real deterministic hybrid keypair so the federation-tier ingest
        // gate (`put_attestation`) verifies the emitted scrub signature.
        let signer = crate::federation::tier_ingest::test_support::local_signer("ciris-client");
        let derived = signer.federation_id().await;
        assert_ne!(derived, "ciris-client", "alias ≠ derived");
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        // Register the key under the DERIVED id (the FK target) carrying
        // "ciris-client"'s REAL pubkeys so the gate's hybrid-verify passes.
        sq.put_live(sweeper_test_key_derived_for(&derived, "ciris-client"))
            .await
            .expect("seed key");

        let input = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "emit-1", "dimension": "trust:identity_binding:v1",
                "score": 1.0, "confidence": 0.9,
            }))
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        let att_id = engine
            .emit_attestation(&signer, input)
            .await
            .expect("emit_attestation (FK holds on the derived id)");

        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.tier,
            crate::federation::types::attestation_tier::FEDERATION,
            "emitted at federation tier"
        );
        assert_eq!(
            row.attesting_key_id, derived,
            "attester is the DERIVED key_id, not the alias (#247 floor)"
        );
        assert_eq!(row.scrub_key_id, derived, "scrub == derived key_id");
        assert_eq!(
            row.attested_key_id, derived,
            "self-attestation default = derived key_id"
        );
        assert_eq!(row.cohort_scope, "federation", "default federation scope");
        assert!(
            crate::federation::edition2::fixture_switch::carried_statement(&row).is_some(),
            "v62: the row carries its edition-2 statement (the composite signature)"
        );
    }

    /// v21.11.0 (CIRISPersist#527) — the LOAD-BEARING cohort_scope is
    /// `EmitAttestationInput::cohort_scope`, NOT the envelope's. A producer
    /// whose ENVELOPE JSON says `federation` but whose INPUT says `self`
    /// stores a `self`-scoped row — the envelope key rides `extra` and is
    /// never lifted onto the row. (This is the exact confusion that made the
    /// server's `config:*` mis-scope look like an envelope-builder typo; the
    /// manifest's `config:*` processor row names the envelope builder, but
    /// THIS is the site that sets the stored, enforced value.)
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_stores_input_cohort_scope_not_envelope_527() {
        use crate::federation::types::{attestation_type::SCORES, cohort_scope};
        use crate::federation::FederationDirectory;

        let signer = crate::federation::tier_ingest::test_support::local_signer("c527");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "c527"))
            .await
            .unwrap();

        // Envelope JSON says federation; the INPUT says self.
        let input = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "e527", "dimension": "trust:identity_binding:v1",
                "score": 1.0, "confidence": 0.9,
                "cohort_scope": "federation",
            }))
            .unwrap(),
            cohort_scope::SELF,
        );
        let att_id = engine.emit_attestation(&signer, input).await.expect("emit");
        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.cohort_scope,
            cohort_scope::SELF,
            "the STORED cohort_scope is the INPUT's (self), never the envelope's (federation)"
        );
    }

    /// v21.11.0 (CIRISPersist#527) — the emit chokepoint REJECTS an empty
    /// cohort_scope (the removed second fail-open): an empty axis is a
    /// producer error, not a silent broadcast-to-federation. `with_envelope`
    /// requires the arg; a struct built with "" is refused at assembly,
    /// before it can be laundered into `federation` and slip past put's
    /// own empty-check.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_rejects_empty_cohort_scope_527() {
        use crate::federation::types::attestation_type::SCORES;

        let signer = crate::federation::tier_ingest::test_support::local_signer("c527e");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "c527e"))
            .await
            .unwrap();

        let input = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "e527e", "dimension": "trust:identity_binding:v1",
                "score": 1.0, "confidence": 0.9,
            }))
            .unwrap(),
            "", // deliberate empty — the only way to reach the assemble guard now.
        );
        let err = engine
            .emit_attestation(&signer, input)
            .await
            .expect_err("an empty cohort_scope must be rejected, never defaulted to federation");
        assert!(
            matches!(err, crate::federation::Error::CohortScopeRejected { .. })
                || format!("{err}").to_lowercase().contains("cohort_scope"),
            "rejection cites cohort_scope: {err:?}"
        );
    }

