    /// #253 — THE deliverable: a **hardware-hybrid** engine
    /// (`with_hardware_signer_hybrid`, which holds only a composed signer and
    /// no external `LocalSigner` to hand to `emit_attestation`) emits a
    /// federation-tier row via `emit_attestation_self`. We register the key
    /// under the engine's `local_derived_key_id()` carrying the HARDWARE
    /// signer's real Ed25519 pubkey + the ML-DSA-65 half's pubkey, so the
    /// federation-tier ingest gate hybrid-verifies the composed scrub sig.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_attestation_self_hardware_hybrid_emits_sqlite() {
        use crate::federation::types::attestation_type::SCORES;
        use crate::federation::FederationDirectory;

        let classical = hw_classical("hw-self-steward");
        let pqc = pqc_half();

        let engine = Engine::with_hardware_signer_hybrid(
            classical.clone(),
            Some(pqc),
            Some("hw-hybrid-pqc".to_owned()),
            "sqlite::memory:",
        )
        .await
        .expect("construct hybrid-hardware engine");

        // The engine has NO external LocalSigner to hand to
        // `emit_attestation` — `emit_attestation_self` is the only path.
        let derived = engine.local_derived_key_id().await.expect("derive");
        let sq = engine.sqlite_backend().expect("sqlite").clone();

        // v62 (E3): the hardware-composed key has no fixture seed, so the
        // engine makes its own key live through the production producer
        // (`register_self_federation_key` writes the edition-2 key:record and
        // returns its identity-ref).
        let registered = engine
            .register_self_federation_key("primitive", None, None)
            .await
            .expect("register the hardware-composed key");
        assert_eq!(
            registered, derived,
            "the derived id is the key's identity-ref"
        );

        let input = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "emit-hw-1", "dimension": "trust:identity_binding:v1",
                "score": 1.0, "confidence": 0.9,
            }))
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        let att_id = engine
            .emit_attestation_self(input)
            .await
            .expect("hardware-hybrid engine emits via the composed signer (#253)");

        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.tier,
            crate::federation::types::attestation_tier::FEDERATION
        );
        assert_eq!(
            row.attesting_key_id, derived,
            "attester == hardware-composed signer's derived key_id"
        );
        assert_eq!(row.scrub_key_id, derived);
        assert!(
            crate::federation::edition2::fixture_switch::carried_statement(&row).is_some(),
            "v62: the row carries its edition-2 statement (the composite signature)"
        );
    }

    /// #252 — `weight: Some(w)` folds onto the assembled row's
    /// `Attestation::weight`; `None` (the default) leaves it `None`. A
    /// weighted `scores` row round-trips its band instead of collapsing to
    /// the `1.0` trust-model default.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_attestation_weight_round_trips_sqlite() {
        use crate::federation::types::attestation_type::SCORES;
        use crate::federation::FederationDirectory;

        let signer = crate::federation::tier_ingest::test_support::local_signer("ciris-weight");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "ciris-weight"))
            .await
            .expect("seed key");
        // v22.0.0 (CIRISPersist#543) — the capacity-band emit below needs a
        // SUBJECT distinct from the attester: `capacity:*` must not be
        // self-attested (CEG §7.5 anti-Goodhart / AV-62), which is now enforced
        // dimension-keyed at `put_attestation`, not just on the `capacity:*`
        // attestation_type namespace.
        let subject = "capacity-subject";
        // Registered via the tier_ingest derivation (not the sweeper helper):
        // the consent grant below is SIGNED by this key, and admission
        // hybrid-verifies it against what is registered here.
        crate::federation::tier_ingest::test_support::register_hybrid_key(&*sq, subject).await;
        // v62 (E3): `subject` is the key's seed; the key is named by its ref.
        let subject_id = crate::federation::edition2::fixture_switch::kid(subject);

        // v22.0.0 (CIRISConstitution#46) — CONSENT BEFORE SCORING. The
        // capacity:* emit below is a federation-tier claim ABOUT `subject`,
        // so it needs S's live `analyze` grant covering this engine's
        // emitting key. Without this row the emit is REFUSED by
        // `check_capacity_consent_admission` — which is not a fixture
        // inconvenience but the gate biting on the node's OWN emit surface:
        // `emit_attestation` stores through `put_attestation`, and the local
        // surface gets no bypass (the inverted AV-77 lesson — a gate that
        // exempted the node's own path would be unreachable from the other
        // side).
        crate::federation::FederationDirectory::put_attestation(
            &*sq,
            crate::federation::SignedAttestation {
                attestation:
                    crate::federation::bootstrap_admission::test_support::consent_scope_row(
                        &uuid::Uuid::new_v4().to_string(),
                        subject,
                        &derived,
                        &format!(
                            "{}:v1",
                            crate::federation::consent::consent_dimension::STATE_GRANTED_PREFIX
                        ),
                        &[crate::federation::admission::ANALYZE_CONSENT_SCOPE],
                        chrono::Utc::now() - chrono::Duration::seconds(60),
                    ),
            },
        )
        .await
        .expect("seed S->P analyze consent (CC#46)");

        // Weighted scores emit (the capacity-band case): weight survives.
        let mut weighted = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "emit-w-1", "dimension": "capacity:sustained_coherence:v1",
                "score": 0.42, "confidence": 0.9,
            }))
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        )
        .with_weight(Some(0.42));
        // Someone else's capacity, not the emitter's own.
        weighted.attested_key_id = Some(subject_id.clone());
        let w_id = engine
            .emit_attestation(&signer, weighted)
            .await
            .expect("weighted emit");
        let w_row = sq.get_attestation(&w_id).await.unwrap().expect("row");
        assert_eq!(
            w_row.weight,
            Some(0.42),
            "Some(w) folds onto Attestation::weight (no collapse to 1.0)"
        );

        // Default (None) emit: weight stays None (pre-9.4.0 behavior).
        let plain = crate::federation::EmitAttestationInput::with_envelope(
            SCORES,
            crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                "id": "emit-w-2", "dimension": "trust:identity_binding:v1",
                "score": 1.0, "confidence": 0.9,
            }))
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        let p_id = engine
            .emit_attestation(&signer, plain)
            .await
            .expect("default emit");
        let p_row = sq.get_attestation(&p_id).await.unwrap().expect("row");
        assert_eq!(p_row.weight, None, "None ⇒ unchanged default");
    }

    /// v25.1.0 (CIRISPersist#569) — **THE GATE BITES THE NODE'S OWN EMIT
    /// SURFACE — AND ONLY WHERE CC 3.4.5 PUT IT.**
    ///
    /// A put-gate that exempted the local emit path would be unreachable from
    /// the only side that matters: this node would happily publish about a
    /// subject who never consented while refusing the identical row from a
    /// peer. [`Engine::emit_attestation`] stores through `put_attestation`, so
    /// it faces `check_capacity_consent_admission` like anyone.
    ///
    /// Witnesses both halves of the boundary on the emit API itself, because a
    /// gate is only as trustworthy as what it lets through:
    /// (a) this node's own unconsented `capacity:*` emit about a third party is
    /// REFUSED with the typed
    /// [`crate::federation::Error::ConsentGateRefused`]; (b) its
    /// `rollback_detected:*` emit about that SAME silent subject ADMITS — CC
    /// 3.4.5 puts the adversarial detector on the abuse-response side of the
    /// line, and a node that could not report a rollback until the rolled-back
    /// party consented would have no detector at all; (c) once the subject
    /// grants `analyze`, the capacity emit admits too.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn emit_attestation_consent_gate_bites_own_surface_569() {
        use crate::federation::types::attestation_type::SCORES;
        use crate::federation::FederationDirectory;

        let signer = crate::federation::tier_ingest::test_support::local_signer("ciris-569");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "ciris-569"))
            .await
            .expect("seed key");
        let subject = "verify-signal-subject";
        crate::federation::tier_ingest::test_support::register_hybrid_key(&*sq, subject).await;
        // v62 (E3): `subject` is the key's seed; the key is named by its ref.
        let subject_id = crate::federation::edition2::fixture_switch::kid(subject);

        const CAPACITY: &str = "capacity:core_identity:v1";
        const ROLLBACK: &str = "rollback_detected:agent_version:v1";

        let emit = |dimension: &str| {
            let mut input = crate::federation::EmitAttestationInput::with_envelope(
                SCORES,
                crate::federation::envelope::EnvelopeCore::from_value(serde_json::json!({
                    "id": uuid::Uuid::new_v4().to_string(),
                    "dimension": dimension,
                    "score": crate::federation::namespace::registry::in_class_score(dimension),
                    "confidence": 0.9,
                }))
                .unwrap(),
                crate::federation::types::cohort_scope::FEDERATION,
            );
            // Someone ELSE's row, not the emitter's own.
            input.attested_key_id = Some(subject_id.clone());
            input
        };

        // (a) The node's OWN capacity emit is not admitted — no bypass for the
        // local path. v62 (E3b r3; CC 2.7.3, fold reason
        // `consent_gate_refused`): the consent gate reads the SUBJECT's grants
        // (other rows), so it HOLDS the emit instead of refusing it — the
        // producer returns the held row's id, and no row is stored until the
        // subject's grant lands.
        let held = engine
            .emit_attestation(&signer, emit(CAPACITY))
            .await
            .expect("#569: the unconsented capacity:* emit's voice is kept (held)");
        assert!(
            sq.get_attestation(&held).await.unwrap().is_none(),
            "#569: this node's own unconsented capacity:* emit is held, never stored"
        );

        // (b) THE OTHER HALF — the adversarial detector fires about the SAME
        // subject, with that subject still silent. If this were gated, a party
        // could suppress its own rollback detection by declining `analyze`.
        let rollback_id = engine
            .emit_attestation(&signer, emit(ROLLBACK))
            .await
            .expect(
                "#569/CC 3.4.5: rollback_detected:* is on the abuse-response side of the line — \
                 it must emit with the subject silent",
            );
        let rollback_row = sq
            .get_attestation(&rollback_id)
            .await
            .unwrap()
            .expect("row");
        assert_eq!(
            crate::federation::admission::envelope_dimension(&rollback_row.attestation_envelope),
            Some(ROLLBACK),
            "#569: and the detector's row landed intact"
        );

        // (c) The subject opens the plane; the capacity emit then admits.
        FederationDirectory::put_attestation(
            &*sq,
            crate::federation::SignedAttestation {
                attestation:
                    crate::federation::bootstrap_admission::test_support::consent_scope_row(
                        &uuid::Uuid::new_v4().to_string(),
                        subject,
                        &derived,
                        &format!(
                            "{}:v1",
                            crate::federation::consent::consent_dimension::STATE_GRANTED_PREFIX
                        ),
                        &[crate::federation::admission::ANALYZE_CONSENT_SCOPE],
                        chrono::Utc::now() - chrono::Duration::seconds(60),
                    ),
            },
        )
        .await
        .expect("seed S->P analyze consent");

        let id = engine
            .emit_attestation(&signer, emit(CAPACITY))
            .await
            .expect("#569: with the subject's live analyze grant, the capacity emit admits");
        let row = sq.get_attestation(&id).await.unwrap().expect("row");
        assert_eq!(
            crate::federation::admission::envelope_dimension(&row.attestation_envelope),
            Some(CAPACITY),
            "#569: and the stored row carries the gated dimension"
        );
    }

    // ── #249 Cut C ── delegates_to / moderation emit ceremonies ───────
    //
    // v9.3.0 (CIRISPersist#249) — round-trips for the typed emit ceremonies
    // over the #248 `emit_attestation` primitive. Each composes
    // `emit_attestation` (no re-hand-roll), so the attester/scrub key is the
    // signer's DERIVED key_id (#247 floor); we additionally assert the
    // emitted edge is ADMISSIBLE by the reader gate it targets
    // (`is_named_moderator` / `is_steward_bound` / the moderation `scores`
    // gate) — proving the moderate-scope tokens match the duty walk.

    /// A `user`-role `federation_keys` row keyed by `derived_key_id` but
    /// carrying `pubkey_label`'s REAL deterministic hybrid pubkeys — so a
    /// federation-tier row attested as `derived_key_id` and signed by
    /// `pubkey_label`'s keys both FK-resolves AND hybrid-verifies, while the
    /// `user` identity_type makes the key steward-bound (clause 1 of
    /// `is_steward_bound`). The steward-bound-authority shape the §11.10
    /// named-moderator walk requires at the root.
    #[cfg(any(feature = "sqlite", feature = "postgres"))]
    fn user_test_key_derived_for(
        derived_key_id: &str,
        pubkey_label: &str,
    ) -> crate::federation::KeyRecord {
        typed_test_key_derived_for(
            derived_key_id,
            pubkey_label,
            crate::federation::types::identity_type::USER,
        )
    }

    /// Seed a `founder_only` community whose sole founder is
    /// `founder_key_id` (already registered + steward-bound). The community's
    /// own key is registered too.
    ///
    /// v62 (E3): `community_seed` is the community key's SEED; the community
    /// is keyed by its identity-ref, which this returns. The community row
    /// itself stays on the earlier typed plane (E0: typed-plane builders are
    /// not flipped), signed with the seed's key and named by the ref.
    #[cfg(any(feature = "sqlite", feature = "postgres"))]
    /// v62 (E3, wave 2 / T1): the community is founded as edition-2
    /// `group:roster` voices (`e2::community_voices`): the community key's
    /// voice and the founder's. Members are named by SEED in the builder
    /// (the earlier-form co-signer signs with the seed); the roster lands
    /// under identity-refs. Now-relative: the community key is not a user key.
    async fn seed_community_with_founder(
        engine: &Engine,
        community_seed: &str,
        founder_key_id: &str,
        founder_pubkey_label: &str,
    ) -> String {
        use crate::federation::edition2::fixture_switch as e2;
        let dir = engine.federation_directory();
        dir.put_live(sweeper_test_key(community_seed))
            .await
            .expect("seed community key");
        assert_eq!(
            e2::kid(founder_pubkey_label),
            founder_key_id,
            "the founder is the key its label seeds"
        );
        let community_id = e2::kid(community_seed);
        let now_ms = e2::ms(chrono::Utc::now());
        let now = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(now_ms as i64)
            .expect("ms instant");
        let community = crate::federation::types::Community {
            prev_head_digest: String::new(),
            charter_digest: String::new(),
            community_key_id: community_seed.into(),
            community_name: "cut-c-community".into(),
            members: vec![crate::federation::types::CommunityMember {
                key_id: founder_pubkey_label.into(),
                joined_at: now,
                role: Some("founder".into()),
            }],
            founded_at: now,
            consensus_protocol: "quorum:1/1".into(),
            policy_blob: None,
            persist_row_hash: String::new(),
        };
        let signed =
            crate::federation::tier_ingest::test_support::sign_community(community_seed, community);
        e2::put_voices(&*dir, &e2::community_voices(&signed, 1, None, now_ms))
            .await
            .expect("seed community");
        community_id
    }

    /// #249 — `grant_delegation` stores a `delegates_to` row whose
    /// attester/scrub == the signer's DERIVED key_id (#247 floor) and whose
    /// `attested_key_id` is the delegate; the row is retrievable via
    /// `list_attestations_by(derived)`.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn grant_delegation_stores_edge_under_derived_key_id_sqlite() {
        use crate::federation::attestation_query::test_support::AllAttestations as _;
        use crate::federation::FederationDirectory;
        let signer = crate::federation::tier_ingest::test_support::local_signer("granter");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(sweeper_test_key_derived_for(&derived, "granter"))
            .await
            .expect("seed granter");
        // The delegate must FK-resolve (attested_key_id).
        sq.put_live(sweeper_test_key("delegate"))
            .await
            .expect("seed delegate");
        let delegate = crate::federation::edition2::fixture_switch::kid("delegate");

        let att_id = engine
            .grant_delegation(
                &signer,
                &delegate,
                vec!["message_io".into(), "review".into()],
                true,
                None,
                crate::federation::admission::DelegationTermBounds::until(
                    chrono::Utc::now() + chrono::Duration::days(90),
                ),
            )
            .await
            .expect("grant_delegation");
        // v62 (E3, round 6): an own-act delegation waits for the delegate's voice.
        land_held_row(&*sq, &att_id).await;

        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.attestation_type,
            crate::federation::types::attestation_type::DELEGATES_TO
        );
        assert_eq!(row.attesting_key_id, derived, "attester == derived (#247)");
        assert_eq!(row.scrub_key_id, derived, "scrub == derived (#247)");
        assert_eq!(row.attested_key_id, delegate, "edge keyed by recipient");
        // Stored + listable by the signer's derived id.
        let by = sq.all_attestations_by(&derived).await.unwrap();
        assert!(by.iter().any(|a| a.attestation_id == att_id));
    }

    /// #249 — `steward_bind` emits an `infra:*`-only `delegates_to` from an
    /// steward-bound (user) signer to a node-role key: it PASSES the CC
    /// 4.4.3.4.3 node-agency gate (so it stores), and afterward
    /// `is_steward_bound(node)` is true (the edge the reader walks).
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn steward_bind_infra_only_passes_node_agency_and_steward_binds_sqlite() {
        use crate::federation::admission::is_steward_bound;
        use crate::federation::types::delegation_scope;
        use crate::federation::FederationDirectory;
        let signer = crate::federation::tier_ingest::test_support::local_signer("owner");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        // Owner is user-role (steward-bound) + verifies at the ingest gate.
        sq.put_live(user_test_key_derived_for(&derived, "owner"))
            .await
            .expect("seed owner");
        // The recipient carries the `node` role (the gate constrains it).
        let node_key = typed_test_key("node-1", crate::federation::types::identity_type::NODE);
        let node_1 = crate::federation::edition2::fixture_switch::kid("node-1");
        sq.put_live(node_key).await.expect("seed node");

        // infra:*-only steward-binding → admissible on a node key.
        let att_id = engine
            .steward_bind(
                &signer,
                &node_1,
                vec![
                    delegation_scope::INFRA_NETWORK_PRESENCE.into(),
                    delegation_scope::INFRA_SERVE.into(),
                ],
                None,
            )
            .await
            .expect("steward_bind infra:* admitted on node key");
        // v62 (E3, round 6): the binding waits for its second signers' voices.
        land_held_row(&*sq, &att_id).await;
        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        // Edge carries infra:* only (passed the node-agency gate).
        let scope = row.attestation_envelope["scope"].as_array().unwrap();
        assert!(
            scope
                .iter()
                .all(|s| s.as_str().unwrap().starts_with("infra:")),
            "steward_bind edge is infra:*-only"
        );
        // The node is now steward-bound (a live delegates_to(U → node), U user).
        assert!(
            is_steward_bound(&*sq, &node_1).await.unwrap(),
            "node is steward-bound after steward_bind"
        );

        // Negative control: an agency:* scope on the SAME node key is NOT
        // admitted by the node-agency gate (so the moderate-scope tokens we add
        // cannot be smuggled as agency onto a node). v62 (E3b r3; wave GC1,
        // CC 2.7.3): the gate reads the RECIPIENT's key record (another row),
        // so it HOLDS the delegation (`node_agency_forbidden`) instead of
        // refusing it: the producer returns the held row's id, and no row is
        // stored.
        let held = engine
            .grant_delegation(
                &signer,
                &node_1,
                vec![delegation_scope::AGENCY_ACT_ON_BEHALF.into()],
                false,
                None,
                crate::federation::admission::DelegationTermBounds::default(),
            )
            .await
            .expect("the agency delegation's voice is kept (held)");
        assert!(
            sq.get_attestation(&held).await.unwrap().is_none(),
            "an agency:* delegation onto a node key is held, never stored"
        );
    }

    /// v16.0.0 (CIRISPersist#433, CC 3.4.12) — the adult-incapacity
    /// guardianship aperture END-TO-END over the Engine emit path: the
    /// (v11.9.0/#309) admission predicate was green but unreachable — plain
    /// `steward_bind` cannot stamp the binding fields. Proves:
    /// `steward_bind_incapacity` onto a witness-attested-incapacitated adult
    /// ADMITS (and the ward is steward-bound); plain `steward_bind` on the
    /// same ward still rejects (the #433 probe shape); a capacitated adult
    /// rejects `target_is_self_sovereign` (presumption of capacity); a
    /// protected domain is never delegable.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn steward_bind_incapacity_aperture_end_to_end_sqlite() {
        use crate::federation::admission::steward_bindings_of;

        let s_signer = crate::federation::tier_ingest::test_support::local_signer("guardian-S");
        let w_signer = crate::federation::tier_ingest::test_support::local_signer("cap-witness");
        let s = s_signer.federation_id().await;
        let w = w_signer.federation_id().await;
        let engine = Engine::with_signer(s_signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(user_test_key_derived_for(&s, "guardian-S"))
            .await
            .expect("seed steward");
        sq.put_live(witness_test_key_derived_for(&w, "cap-witness"))
            .await
            .expect("seed witness");

        // v30.2.0 (CIRISPersist#607) — the witness rung resolves a trust-root
        // conferral now. The node identity is pinned to one this fixture can
        // SIGN as: the accept edge must be signed by the node, and that leg is
        // what makes the check non-circular.
        sq.set_node_key_id(crate::federation::edition2::fixture_switch::kid(
            "cap-node-607",
        ));
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            sq.as_ref(),
            "cap-node-607",
            "cap-root-607",
            &w,
            crate::federation::types::delegation_scope::INFRA_ATTEST_ASSURANCE,
        )
        .await;
        for k in ["ward-A", "adult-B"] {
            let key = typed_test_key(k, crate::federation::types::identity_type::USER);
            sq.put_live(key).await.expect("seed user");
        }
        let ward_a = crate::federation::edition2::fixture_switch::kid("ward-A");
        let adult_b = crate::federation::edition2::fixture_switch::kid("adult-B");

        // The witness attests: S + B + A are adults; A is incapacitated
        // (financial) with the reversible mimics ruled out. All over the REAL
        // emit path (reserved-prefix + witness-targets-subject gates live).
        let witness_emit = |subject: &str, token: &str, id: &str| {
            let mut input = crate::federation::EmitAttestationInput::with_envelope(
                token,
                crate::federation::envelope::EnvelopeCore::from_value(
                    serde_json::json!({ "id": id }),
                )
                .unwrap(),
                crate::federation::types::cohort_scope::FEDERATION,
            );
            input.attested_key_id = Some(subject.to_owned());
            (input, w_signer.clone())
        };
        for (subject, token, id) in [
            (s.as_str(), "age_assurance:government:adult:v1", "sbi-s-age"),
            (
                ward_a.as_str(),
                "age_assurance:government:adult:v1",
                "sbi-a-age",
            ),
            (
                adult_b.as_str(),
                "age_assurance:government:adult:v1",
                "sbi-b-age",
            ),
            (
                ward_a.as_str(),
                "capacity_assurance:panel:financial:incapacitated:v1",
                "sbi-a-cap",
            ),
            (
                ward_a.as_str(),
                "capacity_assurance:reversible_excluded:financial:v1",
                "sbi-a-rev",
            ),
        ] {
            let (input, signer) = witness_emit(subject, token, id);
            engine
                .emit_attestation(&signer, input)
                .await
                .expect("witness attestation admitted");
        }

        // (1) The #433 probe shape. v30.8.0 (CIRISConstitution#87) — a plain
        // `steward_bind` with `delegation_purpose: None` is an UNMARKED edge, so
        // it is now a capability CONFERRAL and is admitted.
        //
        // The property this leg protects is UNCHANGED and still the point: a
        // plain bind CANNOT reach the CC 3.4.12 aperture, because it stamps none
        // of the binding fields. Before the ruling that showed up as a refusal;
        // now it shows up as a grant that confers no custody. Both keep an adult
        // from being stewarded by the back door — and this version also proves
        // the ward is not left half-bound, which the refusal never checked.
        engine
            .steward_bind(&s_signer, &ward_a, vec!["financial".into()], None)
            .await
            .expect("(1) an unmarked steward_bind is a conferral");
        assert!(
            !crate::federation::admission::steward_bindings_of(
                engine.sqlite_backend().expect("sqlite").as_ref(),
                &ward_a,
            )
            .await
            .unwrap()
            .contains(&"inc-S".to_string()),
            "(1) a plain steward_bind must NOT reach the aperture — it stamps no CC 3.4.12 \
             binding fields, so it establishes no custody over the ward"
        );

        // (2) The aperture: a conforming CC 3.4.12 binding ADMITS end-to-end.
        let valid_until = crate::federation::admission::render_signed_instant(
            chrono::Utc::now() + chrono::Duration::days(30),
        );
        let binding_id = engine
            .steward_bind_incapacity(
                &s_signer,
                &ward_a,
                vec!["financial".into()],
                "prior_will_proxy",
                &valid_until,
                None,
                None,
            )
            .await
            .expect("(2) a conforming adult-incapacity guardianship must ADMIT");
        // v62 (E3, round 6): the binding waits for its second signers' voices.
        land_held_row(&*sq, &binding_id).await;
        assert!(
            steward_bindings_of(&*sq, &ward_a)
                .await
                .unwrap()
                .contains(&s),
            "(2) the ward is steward-bound to S"
        );

        // (3) Presumption of capacity: the SAME conforming shape onto a
        // capacitated adult rejects target_is_self_sovereign.
        let err = engine
            .steward_bind_incapacity(
                &s_signer,
                &adult_b,
                vec!["financial".into()],
                "prior_will_proxy",
                &valid_until,
                None,
                None,
            )
            .await
            .expect_err("(3) a capacitated adult stays sovereign");
        assert_eq!(
            err.kind(),
            "federation_user_target_steward_binding_forbidden"
        );
        assert!(
            format!("{err}").contains("target_is_self_sovereign"),
            "got {err}"
        );

        // (4) The apophatic floor: a protected domain is never delegable, even
        // for an attested-incapacitated ward.
        let err = engine
            .steward_bind_incapacity(
                &s_signer,
                &ward_a,
                vec!["voting".into()],
                "prior_will_proxy",
                &valid_until,
                None,
                None,
            )
            .await
            .expect_err("(4) protected domains are never delegable");
        assert!(
            format!("{err}").contains("scope_touches_protected_domain")
                || format!("{err}").contains("scope_exceeds_attested_domains"),
            "got {err}"
        );
    }

    // ── v13.0.0 (CIRISPersist#368 + #367, CC 3.4.11/3.4.13 + CC 3.2) ──
    // Witness-targets-subject age graduation over the REAL emit path, and
    // the minor-guardianship admit + steward-less-minor fail-secure driven
    // end-to-end over `emit_attestation` / `grant_delegation` /
    // `revoke_delegation`.

    /// A `witness`-role `federation_keys` row keyed by `derived_key_id` with
    /// `pubkey_label`'s REAL deterministic hybrid pubkeys — the registered
    /// age-assurance verifier shape the `age_assurance:` reserved-prefix
    /// rule requires of the emitter.
    #[cfg(any(feature = "sqlite", feature = "postgres"))]
    fn witness_test_key_derived_for(
        derived_key_id: &str,
        pubkey_label: &str,
    ) -> crate::federation::KeyRecord {
        typed_test_key_derived_for(
            derived_key_id,
            pubkey_label,
            crate::federation::types::identity_type::WITNESS,
        )
    }

    /// #368 — the witness-targets-subject age flow over the REAL
    /// `Engine::emit_attestation` path (sqlite): a witness names a DIFFERENT
    /// subject via `EmitAttestationInput::attested_key_id` and THAT subject's
    /// `age_band` graduates (witness outranks the subject's own
    /// self-declared rung); the witness CANNOT graduate itself
    /// (attester==attested rejected); a non-witness emitter is still
    /// refused by the unchanged identity gate.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn witness_targets_subject_age_graduation_over_emit_sqlite() {
        use crate::federation::age::{age_band, age_band_fine, AgeBand, AgeBandFine};
        use crate::federation::FederationDirectory;

        let w_signer = crate::federation::tier_ingest::test_support::local_signer("age-witness");
        let t_signer = crate::federation::tier_ingest::test_support::local_signer("age-subject");
        let w = w_signer.federation_id().await;
        let t = t_signer.federation_id().await;
        let engine = Engine::with_signer(w_signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(witness_test_key_derived_for(&w, "age-witness"))
            .await
            .expect("seed witness");
        sq.put_live(user_test_key_derived_for(&t, "age-subject"))
            .await
            .expect("seed subject");

        // v30.2.0 (CIRISPersist#607) — the witness now needs a CONFERRAL, not
        // just the claim. This is the honest operator path: a root charters
        // itself, this node accepts that root, and the root confers
        // infra:attest_assurance on the witness.
        // Pin a node identity the fixture can SIGN as. The accept edge must be
        // signed by the node — that is the leg that makes the check
        // non-circular — and this engine's own signer is the WITNESS, whose
        // registered pubkey is not the helper's derived one. The identity is
        // injectable precisely so a host can state it; here the test states it.
        sq.set_node_key_id(crate::federation::edition2::fixture_switch::kid(
            "age-node-607",
        ));
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            sq.as_ref(),
            "age-node-607",
            "age-root-607",
            &w,
            crate::federation::types::delegation_scope::INFRA_ATTEST_ASSURANCE,
        )
        .await;

        // The subject self-declares MINOR (self rung; attested defaults to
        // the emitter — subject-signed by design).
        let self_minor = crate::federation::EmitAttestationInput::with_envelope(
            "age_self_declared:band:minor:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "wtse-self-minor" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        engine
            .emit_attestation(&t_signer, self_minor)
            .await
            .expect("self-declared minor admits");
        assert_eq!(engine.age_band(&t).await.unwrap(), AgeBand::Minor);

        // WITNESS-TARGETS-SUBJECT: the witness emits `age_assurance:*` ABOUT
        // the subject by carrying it in `attested_key_id` — the #368 surface.
        let mut cross = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:government:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "wtse-w-adult" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        cross.attested_key_id = Some(t.clone());
        let att_id = engine
            .emit_attestation(&w_signer, cross)
            .await
            .expect("witness-targets-subject age_assurance admitted");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(&*sq, &att_id).await;
        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(row.attesting_key_id, w, "attester = the witness");
        assert_eq!(row.attested_key_id, t, "subject rides attested_key_id");
        // The SUBJECT's band graduates (witness outranks its self-minor).
        assert_eq!(
            engine.age_band(&t).await.unwrap(),
            AgeBand::Adult,
            "a witness row ABOUT the subject graduates the SUBJECT's band",
        );
        assert_eq!(
            age_band_fine(&*sq, &t).await.unwrap(),
            AgeBandFine::Adult,
            "the finer resolution graduates too",
        );

        // SELF-graduation via the witness prefix is refused: the same
        // witness emitting with the default (self) attested_key_id.
        let selfie = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:provider:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "wtse-w-self" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        let e = engine
            .emit_attestation(&w_signer, selfie)
            .await
            .expect_err("a subject must not emit its own age assurance");
        assert_eq!(e.kind(), "federation_age_assurance_self_emission_rejected");
        assert_eq!(
            age_band(&*sq, &w).await.unwrap(),
            AgeBand::Unknown,
            "the witness's own band is untouched",
        );

        // Identity gate unchanged: the (non-witness) SUBJECT cross-attesting
        // the witness's age is refused (reserved prefix needs a witness).
        let mut bad = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:provider:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "wtse-t-cross" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        bad.attested_key_id = Some(w.clone());
        let e = engine
            .emit_attestation(&t_signer, bad)
            .await
            .expect_err("a non-witness emitter is refused");
        assert_eq!(e.kind(), "federation_reserved_prefix_emitter_mismatch");
    }

    /// #368 PG twin of
    /// [`witness_targets_subject_age_graduation_over_emit_sqlite`] — the
    /// cross-subject graduation + self-graduation rejection over the live
    /// Postgres `put_attestation` gates (pg/sqlite symmetry). Skips when
    /// `CIRIS_PERSIST_TEST_PG_URL` is unset.
    #[cfg(feature = "postgres")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn witness_targets_subject_age_graduation_over_emit_postgres() {
        use crate::federation::age::{age_band, AgeBand};

        let Some(dsn) = crate::test_pg::dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let run = uuid::Uuid::new_v4().simple().to_string();
        let w_label = format!("age-w-{run}");
        let t_label = format!("age-t-{run}");
        let w_signer = crate::federation::tier_ingest::test_support::local_signer(&w_label);
        let t_signer = crate::federation::tier_ingest::test_support::local_signer(&t_label);
        let w = w_signer.federation_id().await;
        let t = t_signer.federation_id().await;
        let engine = Engine::with_signer(w_signer.clone(), &dsn)
            .await
            .expect("pg engine");
        let pg = engine.postgres_backend().expect("pg backend");
        pg.put_live(witness_test_key_derived_for(&w, &w_label))
            .await
            .expect("seed witness");
        pg.put_live(user_test_key_derived_for(&t, &t_label))
            .await
            .expect("seed subject");

        // v30.2.0 (CIRISPersist#607) — the POSTGRES twin needs the same
        // conferral. Missing a twin is this repo's recurring class, so it is
        // done in the same change rather than found by CI later.
        pg.set_node_key_id(crate::federation::edition2::fixture_switch::kid(
            "age-node-607-pg",
        ));
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            pg.as_ref(),
            "age-node-607-pg",
            "age-root-607-pg",
            &w,
            crate::federation::types::delegation_scope::INFRA_ATTEST_ASSURANCE,
        )
        .await;

        // Subject self-declares minor.
        engine
            .emit_attestation(
                &t_signer,
                crate::federation::EmitAttestationInput::with_envelope(
                    "age_self_declared:band:minor:v1",
                    crate::federation::envelope::EnvelopeCore::from_value(
                        serde_json::json!({ "id": format!("pgw-self-{run}") }),
                    )
                    .unwrap(),
                    crate::federation::types::cohort_scope::FEDERATION,
                ),
            )
            .await
            .expect("self-declared minor admits");
        assert_eq!(engine.age_band(&t).await.unwrap(), AgeBand::Minor);

        // Witness graduates the SUBJECT cross-subject.
        let mut cross = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:government:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": format!("pgw-adult-{run}") }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        cross.attested_key_id = Some(t.clone());
        let cross_id = engine
            .emit_attestation(&w_signer, cross)
            .await
            .expect("witness-targets-subject admitted on postgres");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(pg.as_ref(), &cross_id).await;
        assert_eq!(engine.age_band(&t).await.unwrap(), AgeBand::Adult);

        // Self-graduation via the witness prefix rejected on PG too.
        let e = engine
            .emit_attestation(
                &w_signer,
                crate::federation::EmitAttestationInput::with_envelope(
                    "age_assurance:provider:adult:v1",
                    crate::federation::envelope::EnvelopeCore::from_value(
                        serde_json::json!({ "id": format!("pgw-self-adult-{run}") }),
                    )
                    .unwrap(),
                    crate::federation::types::cohort_scope::FEDERATION,
                ),
            )
            .await
            .expect_err("self-emission rejected on postgres");
        assert_eq!(e.kind(), "federation_age_assurance_self_emission_rejected");
        assert_eq!(age_band(&**pg, &w).await.unwrap(), AgeBand::Unknown);
    }

    /// #367 — the FULL CC 3.2 minor-guardianship flow over the REAL paths
    /// (sqlite): a witness attests T minor (cross-subject, #368) → the
    /// steward-less minor fails secure → S's binding is refused until S is a
    /// PROVEN adult → witness attests S adult → `grant_delegation(S → T)` is
    /// ADMITTED → `revoke_delegation` leaves the minor steward-less again
    /// (fail-secure). An age-unverified user target stays rejected.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn minor_guardianship_grant_and_withdraw_end_to_end_sqlite() {
        use crate::federation::admission::{is_steward_bound, steward_bindings_of};
        use crate::federation::age::AgeBand;
        use crate::federation::types::delegation_scope;

        let w_signer = crate::federation::tier_ingest::test_support::local_signer("mg-witness");
        let s_signer = crate::federation::tier_ingest::test_support::local_signer("mg-steward");
        let w = w_signer.federation_id().await;
        let s = s_signer.federation_id().await;
        let engine = Engine::with_signer(w_signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(witness_test_key_derived_for(&w, "mg-witness"))
            .await
            .expect("seed witness");

        // v30.2.0 (CIRISPersist#607) — the witness rung resolves a trust-root
        // conferral now. The node identity is pinned to one this fixture can
        // SIGN as: the accept edge must be signed by the node, and that leg is
        // what makes the check non-circular.
        sq.set_node_key_id(crate::federation::edition2::fixture_switch::kid(
            "mg-node-607",
        ));
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            sq.as_ref(),
            "mg-node-607",
            "mg-root-607",
            &w,
            crate::federation::types::delegation_scope::INFRA_ATTEST_ASSURANCE,
        )
        .await;
        sq.put_live(user_test_key_derived_for(&s, "mg-steward"))
            .await
            .expect("seed steward");
        // The ward T and an age-unverified control U (emit nothing; plain
        // registered user-role keys).
        let t_key = typed_test_key("mg-ward", crate::federation::types::identity_type::USER);
        let mg_ward = crate::federation::edition2::fixture_switch::kid("mg-ward");
        sq.put_live(t_key).await.expect("seed ward");
        let u_key = typed_test_key(
            "mg-unverified",
            crate::federation::types::identity_type::USER,
        );
        let mg_unverified = crate::federation::edition2::fixture_switch::kid("mg-unverified");
        sq.put_live(u_key).await.expect("seed unverified");

        // Age-unverified user self-anchors (presumption of sovereignty).
        assert!(is_steward_bound(&*sq, &mg_ward).await.unwrap());

        // Witness attests T MINOR (the #368 cross-subject emit).
        let mut minor = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:provider:minor:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "mg-w-minor" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        minor.attested_key_id = Some(mg_ward.clone());
        let minor_id = engine
            .emit_attestation(&w_signer, minor)
            .await
            .expect("witness attests the ward minor");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(&*sq, &minor_id).await;
        assert_eq!(engine.age_band(&mg_ward).await.unwrap(), AgeBand::Minor);
        // A PROVEN minor with no steward fails secure.
        assert!(
            !is_steward_bound(&*sq, &mg_ward).await.unwrap(),
            "a steward-less proven minor must not self-anchor",
        );
        assert!(steward_bindings_of(&*sq, &mg_ward)
            .await
            .unwrap()
            .is_empty());

        // S is not yet a PROVEN adult → the binding is refused.
        let e = engine
            .grant_delegation(
                &s_signer,
                &mg_ward,
                vec![delegation_scope::AGENCY_ACT_ON_BEHALF.into()],
                false,
                None,
                crate::federation::admission::DelegationTermBounds::default(),
            )
            .await
            .expect_err("an unproven granter cannot steward a minor");
        match e {
            crate::federation::Error::UserTargetStewardBindingForbidden { reason, .. } => {
                assert_eq!(reason, "granter_not_adult_user");
            }
            other => panic!("expected UserTargetStewardBindingForbidden, got {other:?}"),
        }

        // Witness attests S ADULT (cross-subject again).
        let mut adult = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:government:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": "mg-w-adult" }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        adult.attested_key_id = Some(s.clone());
        let adult_id = engine
            .emit_attestation(&w_signer, adult)
            .await
            .expect("witness attests the steward adult");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(&*sq, &adult_id).await;
        assert_eq!(engine.age_band(&s).await.unwrap(), AgeBand::Adult);

        // The CC 3.2 positive case: adult user S → proven-minor T ADMITTED
        // over the REAL `grant_delegation` path.
        let grant_id = engine
            .grant_delegation(
                &s_signer,
                &mg_ward,
                vec![delegation_scope::AGENCY_ACT_ON_BEHALF.into()],
                false,
                None,
                crate::federation::admission::DelegationTermBounds::default(),
            )
            .await
            .expect("adult-user → proven-minor guardianship is ADMITTED (CC 3.2)");
        assert!(is_steward_bound(&*sq, &mg_ward).await.unwrap());
        assert_eq!(
            steward_bindings_of(&*sq, &mg_ward).await.unwrap(),
            vec![s.clone()],
            "the minor is steward-bound to exactly S",
        );

        // Withdraw the guardianship → the minor is steward-less again and
        // the liveness predicates fail secure.
        engine
            .revoke_delegation(&s_signer, &grant_id, &mg_ward)
            .await
            .expect("revoke_delegation");
        assert!(
            !is_steward_bound(&*sq, &mg_ward).await.unwrap(),
            "a minor whose only guardianship edge was withdrawn fails secure",
        );
        assert!(
            steward_bindings_of(&*sq, &mg_ward)
                .await
                .unwrap()
                .is_empty(),
            "no anchors remain after the withdraw",
        );

        // v30.8.0 (CIRISConstitution#87) — an age-UNVERIFIED user target now
        // receives a CONFERRAL, not a refusal.
        //
        // `grant_delegation` builds an UNMARKED `delegates_to`. Since the ruling
        // that is a capability grant — giving a person a job — and CC 3.2's
        // presumption of sovereignty is not a reason to refuse someone a job. It
        // is a reason they cannot be OWNED, which is asserted directly below and
        // is the stronger statement: the old refusal only proved this particular
        // call failed; this proves no custody exists however it was reached.
        engine
            .grant_delegation(
                &s_signer,
                &mg_unverified,
                vec![delegation_scope::AGENCY_ACT_ON_BEHALF.into()],
                false,
                None,
                crate::federation::admission::DelegationTermBounds::default(),
            )
            .await
            .expect("an unmarked delegation to an unverified user is a conferral");
        assert!(
            !crate::federation::admission::steward_bindings_of(
                engine.sqlite_backend().expect("sqlite").as_ref(),
                &mg_unverified,
            )
            .await
            .unwrap()
            .contains(&"mg-S".to_string()),
            "the presumption of sovereignty is preserved where it matters: the conferral \
             establishes NO stewardship over the unverified user"
        );
    }

    /// #367 PG twin of
    /// [`minor_guardianship_grant_and_withdraw_end_to_end_sqlite`] — the
    /// witness→minor attest → adult-steward grant → withdraw → fail-secure
    /// arc over the live Postgres gates. Skips when
    /// `CIRIS_PERSIST_TEST_PG_URL` is unset.
    #[cfg(feature = "postgres")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn minor_guardianship_grant_and_withdraw_end_to_end_postgres() {
        use crate::federation::admission::{is_steward_bound, steward_bindings_of};
        use crate::federation::age::AgeBand;
        use crate::federation::types::delegation_scope;

        let Some(dsn) = crate::test_pg::dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let run = uuid::Uuid::new_v4().simple().to_string();
        let w_label = format!("mg-w-{run}");
        let s_label = format!("mg-s-{run}");
        let ward = format!("mg-ward-{run}");
        let w_signer = crate::federation::tier_ingest::test_support::local_signer(&w_label);
        let s_signer = crate::federation::tier_ingest::test_support::local_signer(&s_label);
        let w = w_signer.federation_id().await;
        let s = s_signer.federation_id().await;
        let engine = Engine::with_signer(w_signer.clone(), &dsn)
            .await
            .expect("pg engine");
        let pg = engine.postgres_backend().expect("pg backend");
        pg.put_live(witness_test_key_derived_for(&w, &w_label))
            .await
            .expect("seed witness");

        // v30.2.0 (CIRISPersist#607) — the POSTGRES twin needs the conferral
        // too. Fixing sqlite and missing its twin is this repo's recurring
        // class, so both move in the same change.
        pg.set_node_key_id(crate::federation::edition2::fixture_switch::kid(
            "mg-node-607-pg",
        ));
        crate::federation::admission::r2_test_support::confer_scope_from_trusted_root(
            pg.as_ref(),
            "mg-node-607-pg",
            "mg-root-607-pg",
            &w,
            crate::federation::types::delegation_scope::INFRA_ATTEST_ASSURANCE,
        )
        .await;
        pg.put_live(user_test_key_derived_for(&s, &s_label))
            .await
            .expect("seed steward");
        let t_key = typed_test_key(&ward, crate::federation::types::identity_type::USER);
        pg.put_live(t_key).await.expect("seed ward");
        let ward = crate::federation::edition2::fixture_switch::kid(&ward);

        // Witness attests T minor + S adult (cross-subject, #368).
        let mut minor = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:provider:minor:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": format!("mgp-minor-{run}") }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        minor.attested_key_id = Some(ward.clone());
        let minor_id = engine
            .emit_attestation(&w_signer, minor)
            .await
            .expect("witness attests ward minor");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(pg.as_ref(), &minor_id).await;
        let mut adult = crate::federation::EmitAttestationInput::with_envelope(
            "age_assurance:government:adult:v1",
            crate::federation::envelope::EnvelopeCore::from_value(
                serde_json::json!({ "id": format!("mgp-adult-{run}") }),
            )
            .unwrap(),
            crate::federation::types::cohort_scope::FEDERATION,
        );
        adult.attested_key_id = Some(s.clone());
        let adult_id = engine
            .emit_attestation(&w_signer, adult)
            .await
            .expect("witness attests steward adult");
        // v62 (E3, round 6): a counted row waits for its resolved parties.
        land_held_row(pg.as_ref(), &adult_id).await;
        assert_eq!(engine.age_band(&ward).await.unwrap(), AgeBand::Minor);
        assert_eq!(engine.age_band(&s).await.unwrap(), AgeBand::Adult);
        assert!(
            !is_steward_bound(&**pg, &ward).await.unwrap(),
            "steward-less proven minor fails secure on postgres",
        );

        // Adult user → proven minor: ADMITTED; withdraw → fail-secure.
        let grant_id = engine
            .grant_delegation(
                &s_signer,
                &ward,
                vec![delegation_scope::AGENCY_ACT_ON_BEHALF.into()],
                false,
                None,
                crate::federation::admission::DelegationTermBounds::default(),
            )
            .await
            .expect("guardianship admitted on postgres");
        assert_eq!(
            steward_bindings_of(&**pg, &ward).await.unwrap(),
            vec![s.clone()],
        );
        engine
            .revoke_delegation(&s_signer, &grant_id, &ward)
            .await
            .expect("revoke_delegation");
        assert!(
            !is_steward_bound(&**pg, &ward).await.unwrap(),
            "withdrawn guardianship leaves the minor steward-less (fail-secure)",
        );
        assert!(steward_bindings_of(&**pg, &ward).await.unwrap().is_empty());
    }

    // ── v13.2.0 (CIRISPersist#378, CC 3.2 rc2 single-owner) ──────────────
    // The owner-binding sub-relation over the REAL emit path
    // (`steward_bind(.., Some(owner_binding::PURPOSE))`) + `owner_of`: the
    // purpose arg round-trips onto the wire, a same-owner refresh is
    // idempotent, and `owner_of` is purpose-filtered → ≤1 (an unrelated
    // general delegation does not count). v62.0.0 (kernel pass 2, I2840): a
    // second DISTINCT owner is no longer refused at bind time; its binding is
    // held and two counted owners read as unowned (KERNEL_SEAMS B1, C557).

    /// #378 (sqlite) — `steward_bind(node, infra, Some("responsible_for"))`
    /// stamps the owner-binding wire shape, `owner_of` resolves the single
    /// owner, a same-owner refresh is idempotent, a general (non-ownership)
    /// delegation does NOT count toward `owner_of`, an unbound node is `None`,
    /// and (**I2840**) a second distinct owner's cosigned binding is HELD and
    /// the node then reads as unowned (`AmbiguousNodeOwner`, fail-closed).
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn owner_binding_single_owner_end_to_end_sqlite() {
        use crate::federation::types::{delegation_scope, owner_binding};
        use crate::federation::FederationDirectory;

        let o1_signer = crate::federation::tier_ingest::test_support::local_signer("ob-owner1");
        let o2_signer = crate::federation::tier_ingest::test_support::local_signer("ob-owner2");
        let o1 = o1_signer.federation_id().await;
        let o2 = o2_signer.federation_id().await;
        // v62.0.0 (slice C, CC 3.2 *The first binding (MUST)*): "an
        // owner-binding counts toward ownership only when the node's own key
        // cosigned it". The engine IS the node, so the binding it stores for
        // itself carries its co-scrub (`grant_delegation`).
        let node_signer = crate::federation::tier_ingest::test_support::local_signer("ob-node");
        let node_id = node_signer.federation_id().await;
        let engine = Engine::with_signer(node_signer, "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        // Two user-role would-be owners + a node-only key (owner-binding is
        // infra:*-only, so it passes the node-agency gate on a node key).
        sq.put_live(user_test_key_derived_for(&o1, "ob-owner1"))
            .await
            .expect("seed owner1");
        sq.put_live(user_test_key_derived_for(&o2, "ob-owner2"))
            .await
            .expect("seed owner2");
        let node = typed_test_key_derived_for(
            &node_id,
            "ob-node",
            crate::federation::types::identity_type::NODE,
        );
        sq.put_live(node).await.expect("seed node");
        let infra = vec![
            delegation_scope::INFRA_SERVE.into(),
            delegation_scope::INFRA_NETWORK_PRESENCE.into(),
        ];

        // First owner-binding admits; the purpose arg rides the wire.
        let att_id = engine
            .steward_bind(
                &o1_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("first owner-binding admits");
        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.attestation_envelope["dimension"],
            owner_binding::DIMENSION,
            "owner-binding carries the ownership dimension",
        );
        assert_eq!(
            row.attestation_envelope["delegation_purpose"],
            owner_binding::PURPOSE,
            "owner-binding carries the producer-side purpose marker",
        );
        assert_eq!(
            engine.owner_of(&node_id).await.unwrap(),
            Some(o1.clone()),
            "owner_of resolves the single owner",
        );

        // A refresh by the SAME owner is idempotently admitted.
        engine
            .steward_bind(
                &o1_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("same-owner refresh is idempotent");
        assert_eq!(engine.owner_of(&node_id).await.unwrap(), Some(o1.clone()));

        // A general (non-ownership) delegation from a DIFFERENT user is
        // admitted (it never claims ownership) but does NOT count toward
        // owner_of — the purpose filter keeps ownership single-valued.
        engine
            .steward_bind(&o2_signer, &node_id, infra.clone(), None)
            .await
            .expect("a plain steward-binding is not an owner-binding");
        assert_eq!(
            engine.owner_of(&node_id).await.unwrap(),
            Some(o1.clone()),
            "owner_of ignores the general delegation (purpose-filtered ≤1)",
        );

        // I2840 (kernel pass 2, KERNEL_SEAMS B1 / C557) — a second, DISTINCT
        // owner's binding is HELD, not refused. The engine is the node, so it
        // cosigned it: two counted owners read as unowned, fail-closed, never
        // as the first to arrive.
        let second = engine
            .steward_bind(
                &o2_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("I2840: a second distinct owner's binding is held, not refused");
        assert!(
            sq.get_attestation(&second).await.unwrap().is_some(),
            "I2840: the second binding is stored"
        );
        match engine.owner_of(&node_id).await {
            Err(crate::federation::Error::AmbiguousNodeOwner {
                ref node_key_id,
                ref owners,
            }) => {
                assert_eq!(node_key_id, &node_id);
                assert!(
                    owners.contains(&o1) && owners.contains(&o2),
                    "I2840: both counted owners are named: {owners:?}"
                );
            }
            other => panic!("I2840: two counted owners read as unowned, got {other:?}"),
        }

        // An unbound node reads as unowned.
        let node2 = typed_test_key("ob-node2", crate::federation::types::identity_type::NODE);
        let ob_node2 = crate::federation::edition2::fixture_switch::kid("ob-node2");
        sq.put_live(node2).await.expect("seed node2");
        assert_eq!(engine.owner_of(&ob_node2).await.unwrap(), None);
        // v62.0.0 — a binding of a node that never cosigned it names no owner
        // (CC 3.2, the first binding): this engine is not ob-node2, so the
        // binding it stores carries no ob-node2 co-scrub.
        engine
            .steward_bind(
                &o1_signer,
                &ob_node2,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("an uncosigned owner-binding is held");
        assert_eq!(
            engine.owner_of(&ob_node2).await.unwrap(),
            None,
            "CC 3.2: an owner-binding the node never cosigned names no owner",
        );
    }

    /// #378 PG twin of [`owner_binding_single_owner_end_to_end_sqlite`] — the
    /// same owner-binding / purpose-filtered `owner_of` arc, and I2840's held
    /// second owner, over the live Postgres gates. Skips when `CIRIS_PERSIST_TEST_PG_URL`
    /// is unset.
    #[cfg(feature = "postgres")]
    #[tokio::test]
    #[serial_test::serial(postgres)]
    async fn owner_binding_single_owner_end_to_end_postgres() {
        use crate::federation::types::{delegation_scope, owner_binding};
        use crate::federation::FederationDirectory;

        let Some(dsn) = crate::test_pg::dsn() else {
            eprintln!("skipping: CIRIS_PERSIST_TEST_PG_URL unset");
            return;
        };
        let run = uuid::Uuid::new_v4().simple().to_string();
        let o1_label = format!("ob-o1-{run}");
        let o2_label = format!("ob-o2-{run}");
        let node_label = format!("ob-node-{run}");
        let node2_label = format!("ob-node2-{run}");
        let o1_signer = crate::federation::tier_ingest::test_support::local_signer(&o1_label);
        let o2_signer = crate::federation::tier_ingest::test_support::local_signer(&o2_label);
        let o1 = o1_signer.federation_id().await;
        let o2 = o2_signer.federation_id().await;
        // v62.0.0 (slice C, CC 3.2 *The first binding (MUST)*): the engine IS
        // the node, so the binding it stores for itself carries its co-scrub.
        let node_signer = crate::federation::tier_ingest::test_support::local_signer(&node_label);
        let node_id = node_signer.federation_id().await;
        let engine = Engine::with_signer(node_signer, &dsn)
            .await
            .expect("pg engine");
        let pg = engine.postgres_backend().expect("pg backend");
        pg.put_live(user_test_key_derived_for(&o1, &o1_label))
            .await
            .expect("seed owner1");
        pg.put_live(user_test_key_derived_for(&o2, &o2_label))
            .await
            .expect("seed owner2");
        let node = typed_test_key_derived_for(
            &node_id,
            &node_label,
            crate::federation::types::identity_type::NODE,
        );
        pg.put_live(node).await.expect("seed node");
        let infra = vec![
            delegation_scope::INFRA_SERVE.into(),
            delegation_scope::INFRA_NETWORK_PRESENCE.into(),
        ];

        // First owner-binding admits; purpose rides the wire; owner_of == o1.
        let att_id = engine
            .steward_bind(
                &o1_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("first owner-binding admits");
        let row = pg.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.attestation_envelope["dimension"],
            owner_binding::DIMENSION
        );
        assert_eq!(
            row.attestation_envelope["delegation_purpose"],
            owner_binding::PURPOSE
        );
        assert_eq!(engine.owner_of(&node_id).await.unwrap(), Some(o1.clone()));

        // Same-owner refresh idempotent.
        engine
            .steward_bind(
                &o1_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("same-owner refresh is idempotent");
        assert_eq!(engine.owner_of(&node_id).await.unwrap(), Some(o1.clone()));

        // A general delegation from a different user does not count.
        engine
            .steward_bind(&o2_signer, &node_id, infra.clone(), None)
            .await
            .expect("a plain steward-binding is not an owner-binding");
        assert_eq!(engine.owner_of(&node_id).await.unwrap(), Some(o1.clone()));

        // I2840 (kernel pass 2) — a second distinct owner's binding is held,
        // not refused; cosigned by the node, two counted owners read as
        // unowned (fail-closed).
        let second = engine
            .steward_bind(
                &o2_signer,
                &node_id,
                infra.clone(),
                Some(owner_binding::PURPOSE),
            )
            .await
            .expect("I2840: a second distinct owner's binding is held, not refused");
        assert!(
            pg.get_attestation(&second).await.unwrap().is_some(),
            "I2840: the second binding is stored"
        );
        match engine.owner_of(&node_id).await {
            Err(crate::federation::Error::AmbiguousNodeOwner { ref owners, .. }) => assert!(
                owners.contains(&o1) && owners.contains(&o2),
                "I2840: both counted owners are named: {owners:?}"
            ),
            other => panic!("I2840: two counted owners read as unowned, got {other:?}"),
        }

        // Unbound node → None.
        let node2 = typed_test_key(&node2_label, crate::federation::types::identity_type::NODE);
        pg.put_live(node2).await.expect("seed node2");
        assert_eq!(engine.owner_of(&node2_label).await.unwrap(), None);
    }

    /// v62 (E3b r3) — **an approval of a held bind** (CC 3.3.6.4): the
    /// author statement `statement` restated over the SAME payload, signed by
    /// `signer_seed`'s key and stated as `iss_seed` (a roster key of the
    /// identity approves as the identity, the occurrence arm). The shape
    /// `self_roster_invariants::bodies::occ_voice_on` builds.
    #[cfg(any(feature = "sqlite", feature = "postgres"))]
    fn approval_as(statement: &[u8], signer_seed: &str, iss_seed: &str) -> Vec<u8> {
        use crate::federation::edition2::fixture_switch as e2;
        use ciris_verify_core::cde::Value;
        let (protected, payload) =
            crate::federation::edition2::liveness::statement_parts(statement).expect("a statement");
        let text = |v: Option<&Value>| v.and_then(Value::as_text).map(str::to_owned);
        let row_type = text(protected.get_int(-70001)).expect("row type");
        let family = text(protected.get_int(-70002)).expect("family");
        let sub = text(protected.get_int(15).and_then(|c| c.get_int(2))).expect("sub");
        ciris_verify_core::edition2::sign_row_statement(
            &e2::signing_key(signer_seed),
            &e2::kid(iss_seed),
            &sub,
            &row_type,
            &family,
            &payload,
            vec![],
        )
        .expect("an approval signs")
    }

    /// #249 — the add_moderator ↔ is_named_moderator round-trip: an
    /// steward-bound community founder appoints a moderator with the
    /// `moderate` duty; `is_named_moderator(moderator, community, moderate)`
    /// is true after — proving SCOPE_MODERATE matches the §11.10 duty walk.
    /// Then `remove_moderator` revokes it and the authority no longer holds.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn add_then_remove_moderator_round_trip_sqlite() {
        use crate::federation::admission::is_named_moderator;
        use crate::federation::types::delegation_scope::SCOPE_MODERATE;
        let signer = crate::federation::tier_ingest::test_support::local_signer("founder");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        // Founder: steward-bound (user) authority root of the community.
        sq.put_live(user_test_key_derived_for(&derived, "founder"))
            .await
            .expect("seed founder");
        sq.put_live(sweeper_test_key("moderator"))
            .await
            .expect("seed moderator");
        let moderator = crate::federation::edition2::fixture_switch::kid("moderator");
        let comm_1 = seed_community_with_founder(&engine, "comm-1", &derived, "founder").await;

        // Pre: not yet a moderator.
        assert!(
            !is_named_moderator(&*sq, &moderator, &comm_1, SCOPE_MODERATE)
                .await
                .unwrap(),
            "not a moderator before appointment"
        );

        // Appoint.
        let appt = engine
            .add_moderator(
                &signer,
                &comm_1,
                &moderator,
                SCOPE_MODERATE,
                crate::federation::admission::DelegationTermBounds::until(
                    chrono::Utc::now() + chrono::Duration::days(90),
                ),
            )
            .await
            .expect("add_moderator");
        // v62 (E3, round 6): the appointment waits for the moderator's voice.
        land_held_row(&*sq, &appt).await;
        assert!(
            is_named_moderator(&*sq, &moderator, &comm_1, SCOPE_MODERATE)
                .await
                .unwrap(),
            "is_named_moderator TRUE after add_moderator (SCOPE_MODERATE matches the duty walk)"
        );

        // Remove → the appointment edge is withdrawn; authority gone.
        engine
            .remove_moderator(&signer, &comm_1, &appt, &moderator, SCOPE_MODERATE)
            .await
            .expect("remove_moderator");
        assert!(
            !is_named_moderator(&*sq, &moderator, &comm_1, SCOPE_MODERATE)
                .await
                .unwrap(),
            "is_named_moderator FALSE after remove_moderator (withdraws revokes the edge)"
        );
    }

    /// #249 Cut G1 — the uniform cohort surface round-trips across all three
    /// rostered cohorts (`family` / `community` / `self`) over the SAME read
    /// API: `active_members` / `active_member_keys` / `lookup_group` /
    /// `groups_of`. Backend-generic body run on sqlite + live Postgres.
    ///
    /// v62 (E3, wave 3): the writes are edition-2 statements. The earlier
    /// `add_member_consented` / `revoke_member` / `swap_member` doors took
    /// JSON consent proofs (`AdmitSpec` / `RevokeSpec`), which have no
    /// edition-2 form; their roster effects are now:
    /// - founding: the founder's `group:roster` voice (T1);
    /// - add: the member's proposal + acceptance rows, then the widening
    ///   voice over the held head (T1 v3, I3004);
    /// - remove: the removal voice over the held head;
    /// - swap: widen the new founder, then the old founder's removal.
    ///
    /// The `self` cohort reads O1's edition-2 occurrence binds. Dropped: the
    /// `self` revoke leg (an occurrence eviction is not carried by O1 yet) and
    /// the "self refuses the uniform add" leg (the earlier door).
    #[cfg(any(feature = "sqlite", feature = "postgres"))]
    async fn cohort_surface_roundtrip_body<D>(d: &D, s: &str)
    where
        D: crate::federation::FederationDirectory + ?Sized,
    {
        use crate::federation::cohort::Cohort;
        use crate::federation::edition2::fixture_switch as e2;
        use crate::federation::edition2::ingest::StatementOutcome;
        use crate::federation::membership_acceptance::test_support::{
            acceptance_row, proposal_row,
        };
        use crate::federation::tier_ingest::test_support as ts;
        use crate::federation::types::{self, cohort_scope};

        let founder = format!("g1-founder-{s}");
        let mem_b = format!("g1-memb-{s}");
        let mem_c = format!("g1-memc-{s}");
        let fam = format!("g1-fam-{s}");
        let comm = format!("g1-comm-{s}");
        let ident = format!("g1-ident-{s}");
        let occ1 = format!("g1-occ1-{s}");
        let occ2 = format!("g1-occ2-{s}");

        // Every party is a person (user keys: no end, so a fixed `joined`
        // instant stays covered).
        for k in [&founder, &mem_b, &mem_c, &fam, &comm, &ident, &occ1, &occ2] {
            e2::put_key(d, k, &["user"]).await;
        }
        let joined: chrono::DateTime<chrono::Utc> = "2026-05-01T00:00:00Z".parse().unwrap();
        let now = e2::ms(chrono::Utc::now());
        let landed = |r: Result<StatementOutcome, crate::federation::Error>, what: &str| match r {
            Ok(StatementOutcome::Row { .. }) => {}
            other => panic!("{what}: did not land: {other:?}"),
        };

        landed(
            e2::put_voices(
                d,
                &e2::family_voices(
                    &ts::sign_family(
                        &founder,
                        types::Family {
                            prev_head_digest: String::new(),
                            charter_digest: String::new(),
                            family_key_id: fam.clone(),
                            family_name: "g1-fam".into(),
                            members: vec![types::FamilyMember {
                                key_id: founder.clone(),
                                joined_at: joined,
                                role: Some("founder".into()),
                            }],
                            founded_at: joined,
                            consensus_protocol: types::consensus_protocol::FOUNDER_ONLY.into(),
                            consensus_protocol_entrenched: false,
                            dissolved_at: None,
                            persist_row_hash: String::new(),
                        },
                    ),
                    1,
                    None,
                    now,
                ),
            )
            .await,
            "the family founding",
        );
        landed(
            e2::put_voices(
                d,
                &e2::community_voices(
                    &ts::sign_community(
                        &founder,
                        types::Community {
                            prev_head_digest: String::new(),
                            charter_digest: String::new(),
                            community_key_id: comm.clone(),
                            community_name: "g1-comm".into(),
                            members: vec![types::CommunityMember {
                                key_id: founder.clone(),
                                joined_at: joined,
                                role: Some("founder".into()),
                            }],
                            founded_at: joined,
                            consensus_protocol: "quorum:1/1".into(),
                            policy_blob: None,
                            persist_row_hash: String::new(),
                        },
                    ),
                    1,
                    None,
                    now,
                ),
            )
            .await,
            "the community founding",
        );

        // One widening (proposal + acceptance + the signer's voice over the
        // held head) and one removal, per cohort.
        let widen = |cohort: Cohort, group: String, member: String, role: Option<String>| {
            let founder = founder.clone();
            async move {
                let at = chrono::Utc::now();
                let scope = if cohort == Cohort::Family {
                    cohort_scope::FAMILY
                } else {
                    cohort_scope::COMMUNITY
                };
                let p = proposal_row(
                    &founder,
                    scope,
                    &e2::kid(&group),
                    &member,
                    role.as_deref(),
                    at,
                );
                e2::put_signed(d, &p).await.expect("the proposal");
                e2::put_signed(d, &acceptance_row(&member, &p, at))
                    .await
                    .expect("the acceptance");
                let (head, _) = e2::held_head(d, &e2::kid(&group)).await.expect("head held");
                let voices = if cohort == Cohort::Family {
                    e2::family_widening_voices(
                        &ts::sign_family_membership_widening(
                            &founder,
                            types::FamilyMembershipWidening {
                                family_key_id: group.clone(),
                                member_key_id: member.clone(),
                                joined_at: at,
                                effective_at: at,
                                role,
                                persist_row_hash: String::new(),
                            },
                        ),
                        Some(&head),
                    )
                } else {
                    e2::community_widening_voices(
                        &ts::sign_community_membership_widening(
                            &founder,
                            types::CommunityMembershipWidening {
                                community_key_id: group.clone(),
                                member_key_id: member.clone(),
                                joined_at: at,
                                effective_at: at,
                                role,
                                persist_row_hash: String::new(),
                            },
                        ),
                        Some(&head),
                    )
                };
                e2::put_voices(d, &voices).await
            }
        };
        let remove = |cohort: Cohort, group: String, signer: String, member: String| async move {
            let at = chrono::Utc::now();
            let (head, _) = e2::held_head(d, &e2::kid(&group)).await.expect("head held");
            let voices = if cohort == Cohort::Family {
                e2::family_revocation_voices(
                    &ts::sign_family_membership_revocation(
                        &signer,
                        types::FamilyMembershipRevocation {
                            family_key_id: group.clone(),
                            removed_identity_key_id: member.clone(),
                            removed_at: at,
                            effective_at: at,
                            reason: Some("test".into()),
                            witness_set: Vec::new(),
                            persist_row_hash: String::new(),
                        },
                    ),
                    Some(&head),
                )
            } else {
                e2::community_revocation_voices(
                    &ts::sign_community_membership_revocation(
                        &signer,
                        types::CommunityMembershipRevocation {
                            community_key_id: group.clone(),
                            removed_identity_key_id: member.clone(),
                            removed_at: at,
                            effective_at: at,
                            reason: Some("test".into()),
                            witness_set: Vec::new(),
                            persist_row_hash: String::new(),
                        },
                    ),
                    Some(&head),
                )
            };
            e2::put_voices(d, &voices).await
        };

        // family + community: identical uniform ops, no per-cohort branching.
        for (cohort, group) in [(Cohort::Family, &fam), (Cohort::Community, &comm)] {
            let tag = cohort.as_str();
            let gid = e2::kid(group);
            let m = d
                .active_members(cohort, &gid)
                .await
                .expect("active_members");
            assert_eq!(m.len(), 1, "{tag} starts with founder");
            assert_eq!(m[0].key_id, e2::kid(&founder));

            let g = d
                .lookup_group(cohort, &gid)
                .await
                .expect("lookup_group")
                .expect("group exists");
            assert_eq!(g.cohort, cohort);
            // v61 (CIRISPersist#1123) — the family keeps founder_only;
            // the community, refused it above the family, is quorum:1/1.
            let want = if cohort == Cohort::Family {
                types::consensus_protocol::FOUNDER_ONLY
            } else {
                "quorum:1/1"
            };
            assert_eq!(
                g.consensus_protocol.as_deref(),
                Some(want),
                "{tag} lookup_group carries consensus_protocol"
            );
            assert!(g.name.is_some(), "{tag} lookup_group carries name");

            let gs = d
                .groups_of(cohort, &e2::kid(&founder))
                .await
                .expect("groups_of");
            assert!(
                gs.iter().any(|x| x.group_key_id == gid),
                "{tag} groups_of(founder) contains the group"
            );

            landed(
                widen(cohort, group.clone(), mem_b.clone(), None).await,
                "add mem_b",
            );
            assert_eq!(d.active_members(cohort, &gid).await.unwrap().len(), 2);
            let keys = d
                .active_member_keys(cohort, &gid)
                .await
                .expect("active_member_keys");
            assert_eq!(keys.len(), 2, "{tag} active_member_keys resolves both pins");

            landed(
                remove(cohort, group.clone(), founder.clone(), mem_b.clone()).await,
                "remove mem_b",
            );
            assert_eq!(
                d.active_members(cohort, &gid).await.unwrap().len(),
                1,
                "{tag} revoke drops mem_b"
            );

            // The swap: mem_c joins AS founder (v49 #908: a founder may not
            // leave a room that still has members and no founder), then the
            // old founder leaves.
            landed(
                widen(
                    cohort,
                    group.clone(),
                    mem_c.clone(),
                    Some(crate::federation::admission::MEMBER_ROLE_FOUNDER.to_owned()),
                )
                .await,
                "add mem_c as founder",
            );
            landed(
                remove(cohort, group.clone(), founder.clone(), founder.clone()).await,
                "the old founder leaves",
            );
            let after: Vec<String> = d
                .active_members(cohort, &gid)
                .await
                .unwrap()
                .into_iter()
                .map(|m| m.key_id)
                .collect();
            assert_eq!(after, vec![e2::kid(&mem_c)], "{tag} after swap = {{mem_c}}");
        }

        // self cohort: O1's edition-2 occurrence binds through the SAME read
        // API. A person's devices: the identity authors each bind.
        // v62 (E3b r3; CC 3.3.6.4, the self-roster door): occ1 is a roster
        // change of a one-key self, so the identity's voice lands it. occ2
        // then changes a two-key roster `{ident, occ1}`: the identity's voice
        // is HELD (`Pending`, short of the strict majority) and occ1's
        // approval — its own key, stated as the identity (the occurrence arm)
        // over the same payload — completes it.
        landed(
            e2::put_bind(
                d,
                &ident,
                &ident,
                &occ1,
                types::device_class::SERVER,
                &e2::BindOptions::default(),
            )
            .await,
            "bind the first occurrence",
        );
        {
            let mut opts = e2::BindOptions::default();
            if let Some((h, further)) =
                crate::federation::edition2::occurrence::current_roster_heads(d, &e2::kid(&ident))
                    .await
                    .expect("the identity's roster head")
            {
                opts.head = Some(h);
                opts.further_heads = further;
            }
            let voices = e2::occurrence_bind_voices(
                &ident,
                &ident,
                &occ2,
                types::device_class::SERVER,
                &opts,
            );
            let mut last = None;
            for v in &voices {
                last = Some(
                    e2::put_statement(d, v)
                        .await
                        .expect("a voice of occ2's bind is kept"),
                );
            }
            assert!(
                matches!(last, Some(StatementOutcome::Pending { .. })),
                "the identity's voice alone is short of a two-key roster: {last:?}"
            );
            let approval = approval_as(voices.last().expect("the author's voice"), &occ1, &ident);
            landed(
                e2::put_statement(d, &approval).await,
                "occ1's approval lands occ2's bind",
            );
        }
        let id_ref = e2::kid(&ident);
        let occ_members = d
            .active_members(Cohort::SelfId, &id_ref)
            .await
            .expect("self active_members");
        assert_eq!(occ_members.len(), 2, "self has 2 active occurrences");
        assert!(
            occ_members
                .iter()
                .all(|m| m.role.as_deref() == Some("server")),
            "self RosterMember.role projects device_class"
        );
        let ig = d
            .groups_of(Cohort::SelfId, &e2::kid(&occ1))
            .await
            .expect("groups_of self");
        assert_eq!(ig.len(), 1);
        assert_eq!(ig[0].group_key_id, id_ref, "occ1 resolves to its identity");
        assert!(
            d.lookup_group(Cohort::SelfId, &id_ref)
                .await
                .unwrap()
                .is_some(),
            "self lookup_group on a known identity key"
        );
    }

