    /// v22.0.0 (CIRISPersist#543 / ciris.ai/contextual-integrity) — **the
    /// host-reachability witness** for the deletion-window breach sweep.
    ///
    /// The sweep itself is proven backend-by-backend in
    /// [`crate::federation::deletion_window`]. This test proves the other half,
    /// the one AV-77 taught us costs a whole release when it is skipped: that a
    /// host holding an [`Engine`] can DRIVE it and SEE the signal, without
    /// reaching past the handle into a concrete backend type. A breach signal
    /// nobody can raise is not a breach signal.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn deletion_window_watch_runs_through_the_engine_handle_sqlite() {
        use crate::federation::deletion_window::{kind, watch_witness};
        use crate::federation::HardCaseFilter;

        let signer = crate::federation::tier_ingest::test_support::local_signer("dw-engine");
        let engine = Engine::with_signer(signer, "sqlite::memory:")
            .await
            .expect("engine");
        let dir = engine.federation_directory();
        hold_engine_node_key(&*dir, "dw-engine").await;
        let (breached_id, now) = watch_witness::seed_one_breach(&*dir, "eng").await;

        // THROUGH the handle — no `engine.sqlite_backend()`, no concrete type.
        let report = engine
            .run_deletion_window_watch(now)
            .await
            .expect("the watch is reachable from an Engine");
        assert_eq!(report.breaches, 1, "the Engine handle raises the signal");

        let events = dir
            .list_hard_case_events(HardCaseFilter {
                kind: Some(kind::DELETION_WINDOW_BREACH.to_string()),
                since: None,
                emitter_key_id: None,
            })
            .await
            .expect("list_hard_case_events");
        assert!(
            events
                .iter()
                .any(|e| e.target_key_id.as_deref() == Some(breached_id.as_str())),
            "and the host can observe the evidence it raised"
        );
    }

    /// v24.2.0 (CIRISPersist#564 stage 1) — **the host-reachability witness**
    /// for `is_load_bearing`.
    ///
    /// The predicate itself is proven backend-by-backend against
    /// `&dyn FederationDirectory` in
    /// [`crate::federation::load_bearing::test_support`]. This proves the other
    /// half: a host holding an [`Engine`] can ASK the question and READ the
    /// derivation, without reaching past the handle into a concrete backend
    /// type. #563's own finding was three primitives with zero callers — a
    /// capability nobody can invoke is not shipped, whatever the tests say.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn is_load_bearing_runs_through_the_engine_handle_sqlite() {
        use crate::federation::load_bearing::{LoadBearing, ObjectRef};

        let signer = crate::federation::tier_ingest::test_support::local_signer("lb-engine");
        let engine = Engine::with_signer(signer, "sqlite::memory:")
            .await
            .expect("engine");

        // THROUGH the handle — no `engine.sqlite_backend()`, no concrete type.
        // An object this node does not hold: nothing here depends on it.
        let verdict = engine
            .is_load_bearing(ObjectRef::Attestation {
                attestation_id: uuid::Uuid::new_v4().to_string(),
            })
            .await
            .expect("is_load_bearing is reachable from an Engine");
        assert_eq!(verdict, LoadBearing::No);

        // And a key the corpus knows nothing about is fail-secure Unknown,
        // NOT `No` — the direction that matters, asserted at the host handle
        // because that is where a caller would act on it.
        let verdict = engine
            .is_load_bearing(ObjectRef::KeyRecord {
                key_id: "lb-engine-unknown-key".to_string(),
            })
            .await
            .expect("key-record arm is reachable from an Engine");
        assert!(
            matches!(verdict, LoadBearing::Unknown { .. }),
            "unproven must read Unknown at the host handle, got {verdict:?}"
        );
        assert!(verdict.treated_as_load_bearing());
    }

    /// CIRISPersist#564 stage 2 — **the host-reachability witness** for
    /// `may_release_copy`, and the fail-secure property asserted where a
    /// caller would actually act on it.
    ///
    /// The object under test is the one case that reads
    /// [`LoadBearing::No`] — an object this node does not hold. The
    /// reachability half therefore says "nothing depends on it", and a
    /// primitive that stopped there would hand back a release. It must not:
    /// the anti-entropy conjunct is unsatisfiable on this substrate, so the
    /// answer is `No` with BOTH halves reported.
    ///
    /// If this test ever goes green on `MayRelease::Yes`, something has taught
    /// persist to believe a peer holds a copy without an acknowledgment plane
    /// to prove it.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn may_release_copy_runs_through_the_engine_handle_sqlite() {
        use crate::federation::load_bearing::{AntiEntropy, LoadBearing, MayRelease, ObjectRef};

        let signer = crate::federation::tier_ingest::test_support::local_signer("lb-release");
        let engine = Engine::with_signer(signer, "sqlite::memory:")
            .await
            .expect("engine");

        let object = ObjectRef::Attestation {
            attestation_id: uuid::Uuid::new_v4().to_string(),
        };
        // Precondition: this is the provably-not-load-bearing case.
        assert_eq!(
            engine
                .is_load_bearing(object.clone())
                .await
                .expect("reachability half"),
            LoadBearing::No
        );

        match engine
            .may_release_copy(object)
            .await
            .expect("may_release_copy is reachable from an Engine")
        {
            MayRelease::No {
                load_bearing,
                anti_entropy,
            } => {
                assert_eq!(load_bearing, LoadBearing::No);
                assert!(
                    matches!(anti_entropy, AntiEntropy::Unverifiable { .. }),
                    "residence must read Unverifiable on a substrate with no acknowledgment \
                     plane, got {anti_entropy:?}"
                );
            }
            MayRelease::Yes => panic!(
                "the host handle released a copy on the reachability half ALONE — the \
                 anti-entropy conjunct has become decorative"
            ),
        }

        // Every class is reachable from the host, not just the two stage 1 had.
        for object in [
            ObjectRef::TransportDestination {
                occurrence_key_id: "lb-release-occ".to_string(),
                transport_kind: "websocket".to_string(),
            },
            ObjectRef::FountainContent {
                content_id: "lb-release-content".to_string(),
                corpus_kind: "trace".to_string(),
            },
            ObjectRef::HardCaseEvent {
                event_id: "lb-release-hc".to_string(),
            },
        ] {
            let class = object.class();
            assert!(
                !engine
                    .may_release_copy(object)
                    .await
                    .unwrap_or_else(|e| panic!("{} unreachable from Engine: {e}", class.as_str()))
                    .is_releasable(),
                "{} must not be releasable",
                class.as_str()
            );
        }
    }

    /// #249 — `file_moderation` stores a `moderation:{allegation}` scores
    /// row when the signer is a named moderator (community founder, as-self
    /// duty-holder). Proves the §11.10 EMIT path is feature-free (no
    /// `--features cirisnode`) and admitted by the always-present
    /// `check_delegated_duty_scores_admission` gate.
    #[cfg(feature = "sqlite")]
    #[tokio::test]
    async fn file_moderation_stores_moderation_scores_sqlite() {
        use crate::federation::FederationDirectory;
        let signer = crate::federation::tier_ingest::test_support::local_signer("founder");
        let derived = signer.federation_id().await;
        let engine = Engine::with_signer(signer.clone(), "sqlite::memory:")
            .await
            .expect("engine");
        let sq = engine.sqlite_backend().expect("sqlite").clone();
        sq.put_live(user_test_key_derived_for(&derived, "founder"))
            .await
            .expect("seed founder");
        let comm_1 = seed_community_with_founder(&engine, "comm-1", &derived, "founder").await;

        // The founder IS a named moderator (community authority root,
        // steward-bound) → as-self duty-holder → ADMIT.
        let content_sha = "a".repeat(64);
        let att_id = engine
            .file_moderation(&signer, &content_sha, &comm_1, "moderate", "rogue_action")
            .await
            .expect("file_moderation admitted for a named moderator");
        let row = sq.get_attestation(&att_id).await.unwrap().expect("row");
        assert_eq!(
            row.attestation_type,
            crate::federation::types::attestation_type::SCORES
        );
        assert_eq!(
            row.attestation_envelope["dimension"], "moderation:rogue_action:v1",
            "moderation:{{allegation}}:v1 dimension"
        );
        assert_eq!(row.attesting_key_id, derived, "attester == derived (#247)");
    }

